  1 | /* ── Reset & tokens ─────────────────────────────────────────────────────── */
  2 | *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
  3 | 
  4 | :root {
  5 |   --bg:     #0d1117;
  6 |   --bg2:    #161b22;
  7 |   --bg3:    #21262d;
  8 |   --border: #30363d;
  9 |   --text:   #e6edf3;
 10 |   --muted:  #8b949e;
 11 |   --accent: #58a6ff;
 12 |   --green:  #3fb950;
 13 |   --red:    #f85149;
 14 |   --gold:   #d29922;
 15 |   --purple: #a371f7;
 16 |   --orange: #f0883e;
 17 |   --radius: 8px;
 18 |   --shadow: 0 4px 24px rgba(0,0,0,.5);
 19 |   /* shared column widths — used by both table-head and .row */
 20 |   --c-rank:   32px;
 21 |   --c-spark:  80px;
 22 |   --c-ticker: 100px;
 23 |   --c-price:  80px;
 24 |   --c-chg:    68px;
 25 |   --c-score:  58px;
 26 |   --c-pe:     52px;
 27 |   --c-rsi:    46px;
 28 |   --c-eps:    64px;
 29 |   --c-margin: 64px;
 30 |   --c-cap:    72px;
 31 | }
 32 | 
 33 | /* ── Light mode token overrides ─────────────────────────────────────────── */
 34 | body.light {
 35 |   --bg:     #ffffff;
 36 |   --bg2:    #f6f8fa;
 37 |   --bg3:    #eaeef2;
 38 |   --border: #d0d7de;
 39 |   --text:   #1f2328;
 40 |   --muted:  #656d76;
 41 |   --accent: #0969da;
 42 |   --green:  #1a7f37;
 43 |   --red:    #cf222e;
 44 |   --gold:   #9a6700;
 45 |   --shadow: 0 4px 24px rgba(0,0,0,.12);
 46 | }
 47 | 
 48 | body {
 49 |   background: var(--bg);
 50 |   color: var(--text);
 51 |   font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
 52 |   font-size: 13px;
 53 |   line-height: 1.4;
 54 |   min-height: 100vh;
 55 |   transition: background .2s, color .2s;
 56 | }
 57 | 
 58 | /* ── Toolbar (header + controls in one bar) ── */
 59 | header {
 60 |   background: var(--bg2);
 61 |   border-bottom: 1px solid var(--border);
 62 |   position: sticky;
 63 |   top: 0;
 64 |   z-index: 100;
 65 | }
 66 | .toolbar {
 67 |   max-width: 1400px;
 68 |   margin: 0 auto;
 69 |   padding: 0 20px;
 70 |   height: 48px;
 71 |   display: flex;
 72 |   align-items: center;
 73 |   gap: 20px;
 74 | }
 75 | .logo { display: flex; align-items: center; gap: 8px; font-size: 1rem; font-weight: 700; white-space: nowrap; }
 76 | .logo-ai { color: var(--accent); }
 77 | .toolbar-controls { display: flex; align-items: center; gap: 14px; flex: 1; }
 78 | .toolbar-right { display: flex; align-items: center; gap: 12px; margin-left: auto; white-space: nowrap; }
 79 | 
 80 | /* Controls */
 81 | .control-group { display: flex; align-items: center; gap: 5px; }
 82 | .control-group label { font-size: .72rem; color: var(--muted); text-transform: uppercase; letter-spacing: .05em; white-space: nowrap; }
 83 | .control-group select {
 84 |   background: var(--bg3);
 85 |   border: 1px solid var(--border);
 86 |   color: var(--text);
 87 |   border-radius: 6px;
 88 |   padding: 3px 8px;
 89 |   font-size: .8rem;
 90 |   cursor: pointer;
 91 |   height: 26px;
 92 | }
 93 | 
 94 | /* Buttons */
 95 | .btn { border: none; border-radius: 6px; padding: 4px 12px; font-size: .8rem; font-weight: 600; cursor: pointer; transition: opacity .15s, transform .1s; height: 26px; }
 96 | .btn:hover { opacity: .85; }
 97 | .btn:active { transform: scale(.97); }
 98 | .btn-primary { background: var(--accent); color: #fff; }
 99 | .btn-theme   { background: var(--bg3); color: var(--text); border: 1px solid var(--border); padding: 4px 9px; font-size: .9rem; }
100 | 
101 | .timestamp { color: var(--muted); font-size: .75rem; }
102 | 
103 | /* ── Status banner ── */
104 | .status-banner { max-width: 1400px; margin: 8px auto 0; padding: 7px 20px; border-radius: var(--radius); font-size: .85rem; font-weight: 600; }
105 | .status-banner.error  { background: rgba(248,81,73,.15); border: 1px solid var(--red); color: var(--red); }
106 | .status-banner.hidden { display: none; }
107 | 
108 | /* ── Container ── */
109 | .container { max-width: 1400px; margin: 0 auto; padding: 10px 20px 32px; }
110 | 
111 | /* ── Loading ── */
112 | .loading-screen { display: flex; flex-direction: column; align-items: center; gap: 16px; padding: 60px 0; color: var(--muted); }
113 | .spinner { width: 36px; height: 36px; border: 3px solid var(--border); border-top-color: var(--accent); border-radius: 50%; animation: spin .8s linear infinite; }
114 | @keyframes spin { to { transform: rotate(360deg); } }
115 | 
116 | /* ── Table header row ── */
117 | .table-head {
118 |   display: grid;
119 |   grid-template-columns:
120 |     var(--c-rank) var(--c-spark) var(--c-ticker) var(--c-price)
121 |     var(--c-chg) var(--c-score) var(--c-pe) var(--c-rsi)
122 |     var(--c-eps) var(--c-margin) var(--c-cap);
123 |   align-items: center;
124 |   padding: 0 10px;
125 |   height: 28px;
126 |   border-bottom: 1px solid var(--border);
127 |   margin-bottom: 2px;
128 |   font-size: .68rem;
129 |   color: var(--muted);
130 |   text-transform: uppercase;
131 |   letter-spacing: .05em;
132 | }
133 | .col-rank   { text-align: center; }
134 | .col-price, .col-chg, .col-score, .col-pe, .col-rsi, .col-eps, .col-margin, .col-cap { text-align: right; }
135 | 
136 | /* ── Cards list (one row per stock) ── */
137 | .cards-grid { display: flex; flex-direction: column; gap: 3px; }
138 | .hidden { display: none !important; }
139 | 
140 | /* ── Stock row (compact table-style card) ── */
141 | .card {
142 |   display: grid;
143 |   grid-template-columns:
144 |     var(--c-rank) var(--c-spark) var(--c-ticker) var(--c-price)
145 |     var(--c-chg) var(--c-score) var(--c-pe) var(--c-rsi)
146 |     var(--c-eps) var(--c-margin) var(--c-cap);
147 |   align-items: center;
148 |   padding: 0 10px;
149 |   height: 44px;
150 |   background: var(--bg2);
151 |   border: 1px solid var(--border);
152 |   border-radius: var(--radius);
153 |   cursor: pointer;
154 |   transition: background .12s, border-color .12s;
155 | }
156 | .card:hover { background: var(--bg3); border-color: var(--accent); }
157 | 
158 | /* rank */
159 | .row-rank { text-align: center; font-size: .75rem; color: var(--muted); font-weight: 600; }
160 | .row-rank.top3 { color: var(--gold); font-weight: 700; }
161 | 
162 | /* sparkline cell */
163 | .row-spark { width: var(--c-spark); height: 36px; display: flex; align-items: center; padding: 0 4px; }
164 | .row-spark canvas { display: block; width: 100%; height: 36px; }
165 | 
166 | /* ticker + name stacked */
167 | .row-ticker { display: flex; flex-direction: column; gap: 1px; overflow: hidden; padding-right: 6px; }
168 | .row-ticker-sym { font-size: .85rem; font-weight: 700; white-space: nowrap; }
169 | .row-ticker-name { font-size: .68rem; color: var(--muted); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
170 | 
171 | /* right-aligned cells */
172 | .row-price  { text-align: right; font-size: .82rem; font-weight: 600; padding-right: 6px; }
173 | .row-chg    { text-align: right; padding-right: 6px; }
174 | .row-score  { text-align: right; font-size: .85rem; font-weight: 800; padding-right: 6px; }
175 | .row-pe, .row-rsi, .row-eps, .row-margin, .row-cap { text-align: right; font-size: .78rem; color: var(--muted); padding-right: 6px; }
176 | 
177 | /* change text (no pill background — just color) */
178 | .chg { font-size: .78rem; font-weight: 600; }
179 | .chg.pos { color: var(--green); }
180 | .chg.neg { color: var(--red); }
181 | .chg.neu { color: var(--muted); }
182 | 
183 | /* score colour */
184 | .score-val.high   { color: var(--green); }
185 | .score-val.medium { color: var(--gold); }
186 | .score-val.low    { color: var(--red); }
187 | 
188 | /* Subscore weight tag in modal */
189 | .subscore-weight {
190 |   margin-left: 5px;
191 |   font-size: .68rem;
192 |   color: var(--accent);
193 |   opacity: .8;
194 | }
195 | 
196 | /* Yahoo Finance links */
197 | .yf-link { color: var(--accent); text-decoration: none; }
198 | .yf-link:hover { text-decoration: underline; }
199 | .modal-yf-link { font-size: .75rem; margin-top: 3px; display: inline-block; }
200 | 
201 | /* ── Weight bar ── */
202 | .weight-bar {
203 |   background: var(--bg2);
204 |   border-bottom: 1px solid var(--border);
205 |   padding: 5px 20px;
206 |   display: flex;
207 |   align-items: center;
208 |   gap: 8px;
209 |   flex-wrap: wrap;
210 |   max-width: 100%;
211 |   overflow: hidden;
212 | }
213 | .weight-bar-label {
214 |   font-size: .7rem;
215 |   color: var(--muted);
216 |   text-transform: uppercase;
217 |   letter-spacing: .05em;
218 |   white-space: nowrap;
219 | }
220 | .weight-pill {
221 |   display: inline-flex;
222 |   align-items: center;
223 |   gap: 5px;
224 |   background: var(--bg3);
225 |   border: 1px solid var(--border);
226 |   border-radius: 20px;
227 |   padding: 2px 9px;
228 |   font-size: .72rem;
229 |   white-space: nowrap;
230 | }
231 | .weight-pill-name  { color: var(--muted); }
232 | .weight-pill-val   { color: var(--text); font-weight: 600; }
233 | .weight-pill-track {
234 |   width: 36px;
235 |   height: 4px;
236 |   background: var(--bg);
237 |   border-radius: 2px;
238 |   overflow: hidden;
239 | }
240 | .weight-pill-fill  {
241 |   height: 100%;
242 |   border-radius: 2px;
243 |   background: var(--accent);
244 |   transition: width .4s ease;
245 | }
246 | 
247 | /* ── Score bars (modal) ── */
248 | .subscore-bar-wrap { display: flex; align-items: center; gap: 10px; margin-bottom: 7px; }
249 | .subscore-label { width: 85px; font-size: .78rem; color: var(--muted); flex-shrink: 0; }
250 | .subscore-track { flex: 1; height: 6px; border-radius: 4px; background: var(--bg3); overflow: hidden; }
251 | .subscore-fill  { height: 100%; border-radius: 4px; background: var(--accent); }
252 | .subscore-val   { width: 32px; text-align: right; font-size: .78rem; font-weight: 600; }
253 | 
254 | /* metrics grid (modal) */
255 | .metrics-grid { display: grid; grid-template-columns: 1fr 1fr 1fr; gap: 6px; margin-bottom: 12px; }
256 | .metric { background: var(--bg3); border-radius: 6px; padding: 6px 8px; display: flex; flex-direction: column; gap: 2px; }
257 | .metric-label { font-size: .65rem; color: var(--muted); text-transform: uppercase; letter-spacing: .04em; }
258 | .metric-value { font-size: .88rem; font-weight: 700; }
259 | 
260 | /* 52-week range bar (modal) */
261 | .range-bar-wrap { margin-bottom: 10px; }
262 | .range-bar-labels { display: flex; justify-content: space-between; font-size: .68rem; color: var(--muted); margin-bottom: 3px; }
263 | .range-bar-track { height: 5px; border-radius: 3px; background: var(--bg3); position: relative; }
264 | .range-bar-fill { position: absolute; left: 0; top: 0; height: 100%; border-radius: 3px; background: linear-gradient(90deg, var(--accent), var(--green)); }
265 | .range-bar-dot { position: absolute; top: 50%; transform: translate(-50%,-50%); width: 9px; height: 9px; border-radius: 50%; background: var(--text); border: 2px solid var(--bg2); }
266 | 
267 | /* rationale (modal) */
268 | .rationale-item { font-size: .8rem; color: var(--muted); margin-bottom: 5px; }
269 | 
270 | /* ticker circle (modal) */
271 | .ticker-circle { width: 40px; height: 40px; border-radius: 10px; background: var(--bg3); display: flex; align-items: center; justify-content: center; font-size: .78rem; font-weight: 700; color: var(--accent); flex-shrink: 0; }
272 | 
273 | /* score ring (modal) */
274 | .score-ring { border-radius: 50%; display: inline-flex; align-items: center; justify-content: center; font-weight: 800; border: 2px solid; width: 36px; height: 36px; font-size: .88rem; vertical-align: middle; }
275 | .score-ring.high   { border-color: var(--green); color: var(--green); }
276 | .score-ring.medium { border-color: var(--gold);  color: var(--gold); }
277 | .score-ring.low    { border-color: var(--red);   color: var(--red); }
278 | 
279 | /* ── Legend ── */
280 | .legend { border-top: 1px solid var(--border); padding: 12px 0 24px; }
281 | .legend details summary { font-size: .78rem; color: var(--muted); cursor: pointer; user-select: none; padding: 4px 0; }
282 | .legend details summary:hover { color: var(--text); }
283 | .legend-grid { display: flex; flex-wrap: wrap; gap: 8px; margin-top: 10px; margin-bottom: 10px; }
284 | .legend-item { display: flex; align-items: center; gap: 6px; font-size: .78rem; color: var(--muted); }
285 | .pill { font-size: .68rem; font-weight: 700; padding: 1px 6px; border-radius: 20px; }
286 | .pill-blue   { background: rgba(88,166,255,.15);  color: var(--accent); }
287 | .pill-green  { background: rgba(63,185,80,.15);   color: var(--green); }
288 | .pill-purple { background: rgba(163,113,247,.15); color: var(--purple); }
289 | .pill-orange { background: rgba(240,136,62,.15);  color: var(--orange); }
290 | .pill-red    { background: rgba(248,81,73,.15);   color: var(--red); }
291 | .disclaimer  { font-size: .72rem; color: var(--muted); padding: 8px 12px; background: var(--bg2); border-radius: 6px; border: 1px solid var(--border); }
292 | 
293 | /* ── Modal ── */
294 | .modal-overlay { position: fixed; inset: 0; background: rgba(0,0,0,.72); z-index: 200; display: flex; align-items: center; justify-content: center; padding: 20px; }
295 | .modal { background: var(--bg2); border: 1px solid var(--border); border-radius: var(--radius); max-width: 540px; width: 100%; max-height: 88vh; overflow-y: auto; padding: 22px; position: relative; box-shadow: var(--shadow); }
296 | .modal-close { position: absolute; top: 12px; right: 12px; background: var(--bg3); border: 1px solid var(--border); color: var(--text); border-radius: 6px; width: 26px; height: 26px; font-size: .9rem; cursor: pointer; display: flex; align-items: center; justify-content: center; }
297 | .modal h2 { font-size: 1.15rem; margin-bottom: 2px; }
298 | .modal .modal-sub { color: var(--muted); font-size: .8rem; margin-bottom: 14px; }
299 | .modal-section { margin-bottom: 14px; }
300 | .modal-section h4 { font-size: .7rem; text-transform: uppercase; letter-spacing: .06em; color: var(--muted); margin-bottom: 8px; }
301 | 
302 | /* ── Responsive ── */
303 | @media (max-width: 900px) {
304 |   .col-eps, .col-margin, .col-cap, .row-eps, .row-margin, .row-cap { display: none; }
305 |   .card { grid-template-columns: var(--c-rank) var(--c-spark) var(--c-ticker) var(--c-price) var(--c-chg) var(--c-score) var(--c-pe) var(--c-rsi); }
306 |   .table-head { grid-template-columns: var(--c-rank) var(--c-spark) var(--c-ticker) var(--c-price) var(--c-chg) var(--c-score) var(--c-pe) var(--c-rsi); }
307 | }
308 | @media (max-width: 600px) {
309 |   .col-pe, .col-rsi, .row-pe, .row-rsi { display: none; }
310 |   .card { grid-template-columns: var(--c-rank) 60px var(--c-ticker) var(--c-price) var(--c-chg) var(--c-score); }
311 |   .table-head { grid-template-columns: var(--c-rank) 60px var(--c-ticker) var(--c-price) var(--c-chg) var(--c-score); }
312 |   .toolbar-controls { gap: 8px; }
313 | }

  1 | /* ── StockPicker AI — frontend logic ─────────────────────────────────────── */
  2 | 
  3 | const API = 'http://127.0.0.1:5000/api';
  4 | let stockData   = [];
  5 | let activeWeights = {};  // weights used for the current render
  6 | 
  7 | const SIGNAL_LABELS = {
  8 |   momentum:  'Momentum',
  9 |   ma:        'MA Signal',
 10 |   pe:        'Valuation',
 11 |   eps:       'EPS Growth',
 12 |   debt:      'Debt/Eq',
 13 |   margin:    'Margin',
 14 |   rsi_score: 'RSI',
 15 |   short:     'Short Interest',
 16 | };
 17 | 
 18 | // ── Theme ─────────────────────────────────────────────────────────────────
 19 | function toggleTheme() {
 20 |   const isLight = document.body.classList.toggle('light');
 21 |   document.getElementById('theme-toggle').textContent = isLight ? '☀' : '☾';
 22 |   localStorage.setItem('theme', isLight ? 'light' : 'dark');
 23 | }
 24 | 
 25 | function applyStoredTheme() {
 26 |   if (localStorage.getItem('theme') === 'light') {
 27 |     document.body.classList.add('light');
 28 |     document.getElementById('theme-toggle').textContent = '☀';
 29 |   }
 30 | }
 31 | 
 32 | // ── Boot ──────────────────────────────────────────────────────────────────
 33 | window.addEventListener('DOMContentLoaded', async () => {
 34 |   applyStoredTheme();
 35 |   await loadSectors();
 36 |   await loadStocks();
 37 | });
 38 | 
 39 | // ── Sector dropdown ───────────────────────────────────────────────────────
 40 | async function loadSectors() {
 41 |   try {
 42 |     const res  = await fetch(`${API}/sectors`);
 43 |     const data = await res.json();
 44 |     const sel  = document.getElementById('sector-select');
 45 |     sel.innerHTML = '';
 46 |     data.sectors.forEach(s => {
 47 |       const opt = document.createElement('option');
 48 |       opt.value = s;
 49 |       opt.textContent = s === 'all' ? 'All Sectors' : s;
 50 |       sel.appendChild(opt);
 51 |     });
 52 |   } catch { /* keep default */ }
 53 | }
 54 | 
 55 | // ── Main data loader ──────────────────────────────────────────────────────
 56 | async function loadStocks() {
 57 |   const sector = document.getElementById('sector-select').value;
 58 |   const mode   = document.getElementById('mode-select').value;
 59 |   const url    = `${API}/top-stocks?sector=${encodeURIComponent(sector)}&mode=${mode}`;
 60 | 
 61 |   showLoading(true);
 62 |   hideBanner();
 63 | 
 64 |   try {
 65 |     const res  = await fetch(url);
 66 |     if (!res.ok) throw new Error(`HTTP ${res.status}`);
 67 |     const data = await res.json();
 68 |     stockData     = data.stocks || [];
 69 |     activeWeights = data.weights || {};
 70 | 
 71 |     const ts = data.generated
 72 |       ? 'Updated ' + new Date(data.generated).toLocaleTimeString()
 73 |       : '';
 74 |     document.getElementById('last-updated').textContent = ts;
 75 | 
 76 |     renderWeightBar(activeWeights, data.mode);
 77 |     reRender();
 78 |   } catch (err) {
 79 |     showBanner(`⚠️ Could not reach the backend: ${err.message}. Is the Flask server running?`, 'error');
 80 |   } finally {
 81 |     showLoading(false);
 82 |   }
 83 | }
 84 | 
 85 | // ── Weight pill bar ───────────────────────────────────────────────────────
 86 | function renderWeightBar(weights, mode) {
 87 |   const bar   = document.getElementById('weight-bar');
 88 |   const pills = document.getElementById('weight-pills');
 89 |   if (!weights || !Object.keys(weights).length) {
 90 |     bar.classList.add('hidden');
 91 |     return;
 92 |   }
 93 | 
 94 |   const modeTag  = mode ? ` <span style="color:var(--accent);font-weight:700;">[${mode}]</span>` : '';
 95 |   const maxW     = Math.max(...Object.values(weights));
 96 | 
 97 |   pills.innerHTML = Object.entries(weights).map(([key, val]) => {
 98 |     const pct   = Math.round(val * 100);
 99 |     const barW  = Math.round((val / maxW) * 100);
100 |     const label = SIGNAL_LABELS[key] || key;
101 |     return `<span class="weight-pill">
102 |       <span class="weight-pill-name">${label}</span>
103 |       <span class="weight-pill-track"><span class="weight-pill-fill" style="width:${barW}%"></span></span>
104 |       <span class="weight-pill-val">${pct}%</span>
105 |     </span>`;
106 |   }).join('');
107 | 
108 |   document.querySelector('.weight-bar-label').innerHTML = `🎲 Formula${modeTag}:`;
109 |   bar.classList.remove('hidden');
110 | }
111 | 
112 | // ── Re-render (sort only) ─────────────────────────────────────────────────
113 | function reRender() {
114 |   const sortKey = document.getElementById('sort-select').value;
115 |   const n       = parseInt(document.getElementById('top-n').value, 10);
116 | 
117 |   const sorted  = [...stockData].sort((a, b) => {
118 |     if (sortKey === 'score')    return b.score    - a.score;
119 |     if (sortKey === 'change1d') return b.change1d - a.change1d;
120 |     if (sortKey === 'pe')       return (a.pe ?? 9999) - (b.pe ?? 9999);
121 |     if (sortKey === 'rsi')      return a.rsi - b.rsi;
122 |     return 0;
123 |   }).slice(0, n);
124 | 
125 |   const grid = document.getElementById('cards-grid');
126 |   grid.innerHTML = '';
127 |   sorted.forEach((s, i) => grid.appendChild(buildCard(s, i + 1)));
128 |   grid.classList.remove('hidden');
129 | 
130 |   // show the column header row
131 |   document.getElementById('table-head').classList.remove('hidden');
132 | 
133 |   requestAnimationFrame(() => sorted.forEach(s => drawSparkline(s)));
134 | }
135 | 
136 | // ── Build a compact table-row card ───────────────────────────────────────
137 | function buildCard(s, rank) {
138 |   const card = document.createElement('div');
139 |   card.className = 'card';
140 |   card.dataset.ticker = s.ticker;
141 |   card.addEventListener('click', () => openModal(s));
142 | 
143 |   const scoreClass = s.score >= 72 ? 'high' : s.score >= 55 ? 'medium' : 'low';
144 |   const chgClass   = s.change1d > 0 ? 'pos' : s.change1d < 0 ? 'neg' : 'neu';
145 |   const chgSign    = s.change1d > 0 ? '+' : '';
146 |   const medals     = ['🥇','🥈','🥉'];
147 |   const rankLabel  = rank <= 3 ? medals[rank - 1] : `#${rank}`;
148 | 
149 |   card.innerHTML = `
