/* ── Score history chart (modal) ── */
.score-history-canvas { display: block; width: 100%; border-radius: 6px; }
.score-history-empty  { font-size: .78rem; color: var(--muted); padding: 10px 0; }

/* ── Alert inputs (modal) ── */
.alert-inputs { display: flex; flex-wrap: wrap; align-items: flex-end; gap: 10px; }
.alert-label  { display: flex; flex-direction: column; gap: 4px; font-size: .75rem; color: var(--muted); }
.alert-input  { background: var(--bg3); border: 1px solid var(--border); color: var(--text); border-radius: 6px; padding: 4px 8px; font-size: .82rem; height: 26px; width: 120px; }
.alert-input:focus { outline: none; border-color: var(--accent); }

/* ── Portfolio panel ── */
.portfolio-panel {
  max-width: 1400px;
  margin: 0 auto 0;
  background: var(--bg2);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 16px 20px 12px;
  margin-top: 8px;
}
.portfolio-header { display: flex; align-items: center; justify-content: space-between; margin-bottom: 8px; }
.portfolio-header h3 { font-size: .95rem; font-weight: 700; }
.portfolio-hint { font-size: .75rem; color: var(--muted); margin-bottom: 12px; }

/* Summary row */
.portfolio-summary { display: flex; gap: 24px; flex-wrap: wrap; background: var(--bg3); border-radius: 6px; padding: 10px 14px; margin-bottom: 12px; border: 1px solid var(--border); }
.port-stat { display: flex; flex-direction: column; gap: 2px; }
.port-stat-label { font-size: .68rem; text-transform: uppercase; letter-spacing: .05em; color: var(--muted); }
.port-stat-value { font-size: 1rem; font-weight: 700; color: var(--text); }

/* Portfolio rows */
.portfolio-rows { display: flex; flex-direction: column; gap: 4px; max-height: 320px; overflow-y: auto; }
.port-row {
  display: grid;
  grid-template-columns: 60px 1fr 72px 90px 100px;
  align-items: center;
  gap: 8px;
  padding: 6px 8px;
  border-radius: 6px;
  background: var(--bg3);
  border: 1px solid var(--border);
  font-size: .8rem;
}
.port-row:hover { border-color: var(--accent); }
.port-row-ticker { font-weight: 700; color: var(--accent); }
.port-row-name   { color: var(--muted); font-size: .75rem; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.port-row-price  { color: var(--muted); }
.port-shares-input { background: var(--bg2); border: 1px solid var(--border); color: var(--text); border-radius: 5px; padding: 3px 6px; font-size: .8rem; width: 100%; height: 24px; }
.port-shares-input:focus { outline: none; border-color: var(--accent); }
.port-row-value  { font-weight: 600; text-align: right; color: var(--text); }

/* ── Responsive ── */
@media (max-width: 900px) {
  .col-eps, .col-margin, .col-cap, .row-eps, .row-margin, .row-cap { display: none; }
  .card { grid-template-columns: var(--c-rank) var(--c-spark) var(--c-ticker) var(--c-price) var(--c-chg) var(--c-score) var(--c-pe) var(--c-rsi); }
  .table-head { grid-template-columns: var(--c-rank) var(--c-spark) var(--c-ticker) var(--c-price) var(--c-chg) var(--c-score) var(--c-pe) var(--c-rsi); }
  .port-row { grid-template-columns: 52px 1fr 70px 80px 90px; }
}
@media (max-width: 600px) {
  .col-pe, .col-rsi, .row-pe, .row-rsi { display: none; }
  .card { grid-template-columns: var(--c-rank) 60px var(--c-ticker) var(--c-price) var(--c-chg) var(--c-score); }
  .table-head { grid-template-columns: var(--c-rank) 60px var(--c-ticker) var(--c-price) var(--c-chg) var(--c-score); }
  .toolbar-controls { gap: 8px; }
  .custom-ticker-group { display: none; }
  .port-row { grid-template-columns: 52px 1fr 80px 86px; }
  .port-row-price { display: none; }
}

