@app.route("/api/recommend", methods=["POST"])
def recommend():
    """
    Accept a portfolio payload and return structured recommendations.

    Request body (JSON):
      {
        "holdings": [
          { "ticker": "AAPL", "shares": 10, "score": 74.2, "currentPrice": 189.5,
            "change1d": 0.8, "rsi": 58, "sector": "Technology",
            "subScores": { "momentum": 80, "pe": 60, ... },
            "pe": 28, "epsGrowth": 12, "profitMargin": 25,
            "debtToEquity": 0.5, "marketCap": 2900000000000 },
          ...
        ]
      }

    Response:
      {
        "health": { "score": 72, "label": "Good", "summary": "..." },
        "concentration": [ { "sector": "Technology", "pct": 65.2 }, ... ],
        "recommendations": [
          {
            "type": "trim"|"add"|"hold"|"new_idea"|"rebalance",
            "ticker": "AAPL",
            "title": "...",
            "reason": "...",
            "urgency": "high"|"medium"|"low"
          }, ...
        ]
      }
    """
    body = request.get_json(force=True, silent=True) or {}
    holdings = body.get("holdings", [])

    if not holdings:
        return jsonify({"error": "No holdings provided"}), 400

    # ── Derived values ────────────────────────────────────────────────────────
    total_value = sum(h["shares"] * h["currentPrice"] for h in holdings)
    if total_value == 0:
        return jsonify({"error": "Portfolio has no value"}), 400

    # Sector concentration map  { sector: pct_of_total }
    sector_values: dict[str, float] = {}
    for h in holdings:
        sector = h.get("sector", "Unknown")
        sector_values[sector] = sector_values.get(sector, 0) + h["shares"] * h["currentPrice"]

    concentration = sorted(
        [{"sector": s, "pct": round(v / total_value * 100, 1)} for s, v in sector_values.items()],
        key=lambda x: x["pct"], reverse=True
    )

    # Weighted-average score
    w_score = sum(h["score"] * h["shares"] * h["currentPrice"] for h in holdings) / total_value
    # Weighted-average RSI
    w_rsi   = sum(h.get("rsi", 50) * h["shares"] * h["currentPrice"] for h in holdings) / total_value

    # ── Portfolio health score (0-100) ────────────────────────────────────────
    diversification_penalty = 0
    top_sector_pct = concentration[0]["pct"] if concentration else 0
    if top_sector_pct > 60: diversification_penalty = 20
    elif top_sector_pct > 45: diversification_penalty = 10
    elif top_sector_pct > 35: diversification_penalty = 5

    rsi_penalty = 0
    overbought = [h for h in holdings if h.get("rsi", 50) > 72]
    if len(overbought) >= len(holdings) * 0.5: rsi_penalty = 10
    elif overbought: rsi_penalty = 5

    health_score = max(0, min(100, round(w_score - diversification_penalty - rsi_penalty)))
    if health_score >= 72:   health_label = "Strong"
    elif health_score >= 58: health_label = "Good"
    elif health_score >= 44: health_label = "Fair"
    else:                    health_label = "Weak"

    # ── Generate recommendations ──────────────────────────────────────────────
    recs = []

    for h in holdings:
        ticker = h["ticker"]
        score  = h.get("score", 50)
        rsi    = h.get("rsi", 50)
        weight = h["shares"] * h["currentPrice"] / total_value * 100  # % of portfolio

        sub = h.get("subScores", {})
        pe   = h.get("pe")
        eps  = h.get("epsGrowth")
        margin = h.get("profitMargin")
        de   = h.get("debtToEquity")

        # --- TRIM signals ---
        trim_reasons = []
        if score < 42:
            trim_reasons.append(f"AI score of {score} is weak across multiple signals")
        if rsi > 75:
            trim_reasons.append(f"RSI of {rsi} is overbought — short-term pullback risk")
        if sub.get("momentum", 50) > 85 and weight > 15:
            trim_reasons.append(f"Strong momentum ({sub['momentum']}) may be priced in with a {weight:.1f}% portfolio weight")
        if pe and pe > 60:
            trim_reasons.append(f"Forward P/E of {pe} appears stretched")

        if trim_reasons:
            recs.append({
                "type": "trim",
                "ticker": ticker,
                "title": f"Consider trimming {ticker}",
                "reasons": trim_reasons,
                "urgency": "high" if score < 35 or rsi > 80 else "medium",
            })
            continue  # don't also suggest adding

        # --- ADD / HOLD signals ---
        add_reasons = []
        if score >= 72 and rsi < 68:
            add_reasons.append(f"AI score of {score} is strong and RSI of {rsi} is not overbought")
        if sub.get("eps", 50) >= 80:
            add_reasons.append(f"EPS growth sub-score of {sub['eps']} signals accelerating earnings")
        if sub.get("ma", 50) >= 90:
            add_reasons.append("Trading above both 50-day and 200-day moving averages (golden cross)")
        if de is not None and de < 0.5 and score >= 65:
            add_reasons.append(f"Low D/E of {de} with solid fundamentals — financial resilience")
        if margin and margin > 20 and score >= 65:
            add_reasons.append(f"High profit margin of {margin}% — durable competitive advantage")

        if add_reasons:
            recs.append({
                "type": "add",
                "ticker": ticker,
                "title": f"Add to {ticker}",
                "reasons": add_reasons,
                "urgency": "medium" if score >= 80 else "low",
            })
        else:
            recs.append({
                "type": "hold",
                "ticker": ticker,
                "title": f"Hold {ticker}",
                "reasons": [f"Score of {score} is adequate — no immediate action needed"],
                "urgency": "low",
            })

    # --- REBALANCE: over-concentrated sectors ---
    for c in concentration:
        if c["pct"] > 45:
            recs.append({
                "type": "rebalance",
                "ticker": None,
                "title": f"Rebalance {c['sector']} concentration",
                "reasons": [
                    f"{c['sector']} makes up {c['pct']}% of your portfolio",
                    "Consider spreading exposure across other sectors to reduce single-sector risk",
                ],
                "urgency": "high" if c["pct"] > 60 else "medium",
            })

    # Sort: high urgency first, then by type priority
    type_order = {"trim": 0, "rebalance": 1, "add": 2, "hold": 3, "new_idea": 4}
