    Body: { "holdings": [ { ticker, shares, score, currentPrice, rsi, sector,
                             subScores, pe, epsGrowth, profitMargin, debtToEquity }, ... ] }
    """
    body     = request.get_json(force=True, silent=True) or {}
    holdings = body.get("holdings", [])
