    if total_value == 0:
        return jsonify({"error": "Portfolio has no value"}), 400

    # ── Sector concentration ──────────────────────────────────────────────────
    sector_values: dict = {}
    for h in holdings:
        s = h.get("sector", "Unknown")
        sector_values[s] = sector_values.get(s, 0) + h["shares"] * h["currentPrice"]

    concentration = sorted(
        [{"sector": s, "pct": round(v / total_value * 100, 1)} for s, v in sector_values.items()],
        key=lambda x: x["pct"], reverse=True
    )

    # ── Weighted averages ─────────────────────────────────────────────────────
    w_score = sum(h["score"] * h["shares"] * h["currentPrice"] for h in holdings) / total_value
    w_rsi   = sum(h.get("rsi", 50) * h["shares"] * h["currentPrice"] for h in holdings) / total_value

    # ── Portfolio health score ────────────────────────────────────────────────
    top_pct = concentration[0]["pct"] if concentration else 0
    div_pen = 20 if top_pct > 60 else (10 if top_pct > 45 else (5 if top_pct > 35 else 0))
    overbought_count = sum(1 for h in holdings if h.get("rsi", 50) > 72)
    rsi_pen = 10 if overbought_count >= len(holdings) * 0.5 else (5 if overbought_count else 0)
    health_score = max(0, min(100, round(w_score - div_pen - rsi_pen)))
    health_label = ("Strong" if health_score >= 72 else "Good" if health_score >= 58
