    type_order    = {"trim": 0, "rebalance": 1, "add": 2, "hold": 3}
    urgency_order = {"high": 0, "medium": 1, "low": 2}
    recs.sort(key=lambda r: (urgency_order.get(r["urgency"], 3), type_order.get(r["type"], 4)))

    # ── Health summary ────────────────────────────────────────────────────────
    n_trim = sum(1 for r in recs if r["type"] == "trim")
    n_add  = sum(1 for r in recs if r["type"] == "add")
    n_rb   = sum(1 for r in recs if r["type"] == "rebalance")
