/* Action cards */
.rec-section-title { font-size: .7rem; text-transform: uppercase; letter-spacing: .05em; color: var(--muted); margin: 14px 0 6px; }
.rec-cards         { display: flex; flex-direction: column; gap: 6px; }
.rec-card {
  display: flex; align-items: flex-start; gap: 10px;
  background: var(--bg3); border: 1px solid var(--border);
  border-radius: 8px; padding: 10px 12px;
  border-left-width: 3px;
}
.rec-card.trim      { border-left-color: var(--red); }
.rec-card.add       { border-left-color: var(--green); }
