521 | /** Save the current score for each ticker with a UTC timestamp. */
522 | function persistScoreHistory(stocks) {
523 |   let history = {};
524 |   try { history = JSON.parse(localStorage.getItem(LS_SCORES) || '{}'); } catch {}
525 |   const ts = Date.now();
526 |   stocks.forEach(s => {
527 |     if (!history[s.ticker]) history[s.ticker] = [];
528 |     // Only append if the last entry was > 5 minutes ago (avoid duplicates on rapid refresh)
529 |     const last = history[s.ticker].at(-1);
530 |     if (!last || ts - last.ts > 5 * 60 * 1000) {
531 |       history[s.ticker].push({ ts, score: s.score });
532 |     }
533 |     // Keep only the last 60 data points per ticker
534 |     if (history[s.ticker].length > 60) history[s.ticker] = history[s.ticker].slice(-60);
535 |   });
536 |   try { localStorage.setItem(LS_SCORES, JSON.stringify(history)); } catch {}
537 | }
