784 |   const ticker = (input.value || '').trim().toUpperCase();
785 |   if (!ticker) return;
786 | 
787 |   showBanner(`⏳ Fetching ${ticker}…`, 'info');
788 | 
789 |   try {
790 |     const mode = document.getElementById('mode-select').value;
791 |     const res  = await fetch(`${API}/stock/${encodeURIComponent(ticker)}?mode=${mode}`);
792 |     if (!res.ok) throw new Error(`${ticker} not found or could not be scored (HTTP ${res.status})`);
793 |     const s = await res.json();
794 |     if (s.error) throw new Error(s.error);
