 224 |     [...grid.children].map(el => el.dataset.ticker)
 225 |   );
 226 | 
 227 |   // Add new cards (hidden offscreen until positioned)
 228 |   const newTickers = [...visibleTickers].filter(t => !existingTickers.has(t));
 229 |   newTickers.forEach(ticker => {
 230 |     const s    = sorted.find(x => x.ticker === ticker);
 231 |     const i    = sorted.indexOf(s);
 232 |     const hue  = Math.round((i / sorted.length) * 360);
 233 |     const card = buildCard(s, i + 1, hue);
 234 |     card.style.opacity = '0';
 235 |     grid.appendChild(card);
 236 |     drawSparkline(s);
 237 |   });
 238 | 
 239 |   // Remove cards no longer in the visible set
 240 |   [...grid.children].forEach(el => {
 241 |     if (!visibleTickers.has(el.dataset.ticker)) el.remove();
 242 |   });
 243 | 
 244 |   // Update rank labels and hues for every card
 245 |   sorted.forEach((s, i) => {
 246 |     const card = grid.querySelector(`[data-ticker="${s.ticker}"]`);
 247 |     if (!card) return;
 248 |     const hue = Math.round((i / sorted.length) * 360);
 249 |     card.style.setProperty('--card-hue', hue);
 250 |     const medals    = ['🥇','🥈','🥉'];
 251 |     const rankLabel = (i + 1) <= 3 ? medals[i] : `#${i + 1}`;
 252 |     const rankEl    = card.querySelector('.row-rank');
 253 |     if (rankEl) {
 254 |       rankEl.textContent = rankLabel;
 255 |       rankEl.className   = `row-rank${(i + 1) <= 3 ? ' top3' : ''}`;
 256 |     }
 257 |   });
 258 | 
 259 |   // ── FLIP: record positions BEFORE reorder ──────────────────────────────────
 260 |   const first = {};
 261 |   [...grid.children].forEach(el => {
 262 |     first[el.dataset.ticker] = el.getBoundingClientRect().top;
 263 |   });
 264 | 
 265 |   // ── Reorder DOM nodes to match new sort ───────────────────────────────────
 266 |   sorted.forEach(s => {
 267 |     const card = grid.querySelector(`[data-ticker="${s.ticker}"]`);
 268 |     if (card) grid.appendChild(card);   // moves to end; sorted order is preserved
 269 |   });
 270 | 
 271 |   // ── FLIP: compute delta and animate each card ─────────────────────────────
 272 |   sorted.forEach((s, i) => {
 273 |     const card = grid.querySelector(`[data-ticker="${s.ticker}"]`);
 274 |     if (!card) return;
 275 | 
 276 |     const isNew = newTickers.includes(s.ticker);
 277 |     if (isNew) {
 278 |       // New cards fade + slide in
 279 |       card.style.transition = 'none';
 280 |       card.style.transform  = 'translateX(24px)';
 281 |       card.style.opacity    = '0';
 282 |       requestAnimationFrame(() => {
 283 |         card.style.transition = 'transform 0.38s cubic-bezier(0.22,0.61,0.36,1), opacity 0.3s ease';
 284 |         card.style.transform  = '';
 285 |         card.style.opacity    = '';
 286 |       });
 287 |       return;
 288 |     }
 289 | 
 290 |     const last  = card.getBoundingClientRect().top;
 291 |     const delta = first[s.ticker] - last;
 292 | 
 293 |     if (Math.abs(delta) < 1) return;  // already in place — skip
 294 | 
 295 |     // Snap card back to where it was (visually), then animate to final spot
 296 |     card.style.transition = 'none';
 297 |     card.style.transform  = `translateY(${delta}px)`;
 298 | 
 299 |     requestAnimationFrame(() => {
 300 |       requestAnimationFrame(() => {
 301 |         card.style.transition = 'transform 0.42s cubic-bezier(0.22,0.61,0.36,1)';
 302 |         card.style.transform  = '';
 303 |       });
 304 |     });
 305 |   });
 306 | 
 307 |   // Scramble a random ticker after the FLIP moves settle
 308 |   setTimeout(() => scrambleRandomCard(grid, sorted), 500);
 309 | }
