 883 | function startFloatingBtn() {
 884 |   const btn = document.getElementById('random-ticker-btn');
 885 |   if (!btn) return;
 886 |   // Random starting position
 887 |   _floatX = Math.random() * (window.innerWidth  - (btn.offsetWidth  || 90));
 888 |   _floatY = Math.random() * (window.innerHeight - (btn.offsetHeight || 26));
 889 |   // Random direction, consistent speed
 890 |   const angle = Math.random() * 2 * Math.PI;
 891 |   const speed = 2.5;
 892 |   _floatVX = Math.cos(angle) * speed;
 893 |   _floatVY = Math.sin(angle) * speed;
 894 |   _floatRafId = requestAnimationFrame(_floatLoop);
 895 |   _scheduleNextPause();
 896 | }
