 539 | /** Draw a compact line chart of score-over-time onto #score-history-canvas. */
 540 | function drawScoreHistoryChart(ticker) {
 541 |   let history = {};
 542 |   try { history = JSON.parse(localStorage.getItem(LS_SCORES) || '{}'); } catch {}
 543 |   const points = history[ticker] || [];
 544 | 
 545 |   const canvas  = document.getElementById('score-history-canvas');
 546 |   const emptyEl = document.getElementById('score-history-empty');
 547 |   if (!canvas) return;
 548 | 
 549 |   if (points.length < 2) {
 550 |     canvas.style.display = 'none';
 551 |     emptyEl && emptyEl.classList.remove('hidden');
 552 |     return;
 553 |   }
 554 |   emptyEl && emptyEl.classList.add('hidden');
 555 |   canvas.style.display = 'block';
 556 | 
 557 |   const dpr = window.devicePixelRatio || 1;
 558 |   const W   = canvas.parentElement.clientWidth || 400;
 559 |   const H   = 80;
 560 |   canvas.width  = W * dpr;
 561 |   canvas.height = H * dpr;
 562 |   canvas.style.width  = W + 'px';
 563 |   canvas.style.height = H + 'px';
 564 | 
 565 |   const ctx = canvas.getContext('2d');
 566 |   ctx.scale(dpr, dpr);
 567 | 
 568 |   const scores = points.map(p => p.score);
 569 |   const minS   = Math.min(...scores);
 570 |   const maxS   = Math.max(...scores);
 571 |   const range  = Math.max(maxS - minS, 5);
 572 |   const pad    = { t: 6, b: 18, l: 6, r: 6 };
 573 |   const iW     = W - pad.l - pad.r;
 574 |   const iH     = H - pad.t - pad.b;
 575 | 
 576 |   const xFn = i => pad.l + (i / (points.length - 1)) * iW;
 577 |   const yFn = v => pad.t + iH - ((v - minS) / range) * iH;
 578 | 
 579 |   ctx.fillStyle = '#21262d';
 580 |   ctx.fillRect(0, 0, W, H);
 581 | 
 582 |   const grad = ctx.createLinearGradient(0, pad.t, 0, pad.t + iH);
 583 |   grad.addColorStop(0, 'rgba(88,166,255,0.35)');
 584 |   grad.addColorStop(1, 'rgba(88,166,255,0.02)');
 585 |   ctx.beginPath();
 586 |   ctx.moveTo(xFn(0), yFn(scores[0]));
 587 |   scores.forEach((v, i) => { if (i > 0) ctx.lineTo(xFn(i), yFn(v)); });
 588 |   ctx.lineTo(xFn(scores.length - 1), pad.t + iH);
 589 |   ctx.lineTo(xFn(0), pad.t + iH);
 590 |   ctx.closePath();
 591 |   ctx.fillStyle = grad;
 592 |   ctx.fill();
 593 | 
 594 |   ctx.beginPath();
 595 |   ctx.moveTo(xFn(0), yFn(scores[0]));
 596 |   scores.forEach((v, i) => { if (i > 0) ctx.lineTo(xFn(i), yFn(v)); });
 597 |   ctx.strokeStyle = '#58a6ff';
 598 |   ctx.lineWidth   = 2;
 599 |   ctx.lineJoin    = 'round';
 600 |   ctx.stroke();
 601 | 
 602 |   const special = new Set([0, scores.length - 1,
 603 |     scores.indexOf(Math.min(...scores)), scores.indexOf(Math.max(...scores))]);
 604 |   ctx.textAlign = 'center';
 605 |   special.forEach(i => {
 606 |     const x = xFn(i), y = yFn(scores[i]);
 607 |     ctx.beginPath();
 608 |     ctx.arc(x, y, 2.5, 0, Math.PI * 2);
 609 |     ctx.fillStyle = '#58a6ff';
 610 |     ctx.fill();
 611 |     const labelY = y < pad.t + 12 ? y + 12 : y - 5;
 612 |     ctx.fillStyle = '#8b949e';
 613 |     ctx.font = '9px sans-serif';
 614 |     ctx.fillText(scores[i], x, labelY);
 615 |   });
 616 | 
 617 |   ctx.fillStyle = '#8b949e';
 618 |   ctx.font = '9px sans-serif';
 619 |   ctx.textAlign = 'left';
 620 |   ctx.fillText(fmtDate(points[0].ts), pad.l, H - 4);
 621 |   ctx.textAlign = 'right';
 622 |   ctx.fillText(fmtDate(points.at(-1).ts), W - pad.r, H - 4);
 623 | }
 624 | 
 625 | function fmtDate(ts) {
 626 |   const d = new Date(ts);
 627 |   return `${d.getMonth()+1}/${d.getDate()} ${d.getHours()}:${String(d.getMinutes()).padStart(2,'0')}`;
 628 | }
