 814 | const FALLBACK_TICKERS = [
 815 |   'AAPL','MSFT','GOOGL','AMZN','META','NVDA','TSLA','JPM','V','UNH',
 816 |   'HD','PG','MA','XOM','BAC','PFE','DIS','NFLX','ADBE','CRM',
