 900 |     ? stockData.map(s => s.ticker)
 901 | 
 902 |     : FALLBACK_TICKERS;
 903 |   const ticker = pool[Math.floor(Math.random() * pool.length)];
 904 |   const input  = document.getElementById('custom-ticker-input');
 905 |   input.value  = ticker;
 906 |   lookupCustomTicker();
 907 | }
