   1 | /* ── StockPicker AI — frontend logic ─────────────────────────────────────── */
   2 | 
   3 | const API = 'http://127.0.0.1:5000/api';
   4 | let stockData   = [];
   5 | let activeWeights = {};  // weights used for the current render
   6 | 
   7 | const SIGNAL_LABELS = {
   8 |   momentum:  'Momentum',
   9 |   ma:        'MA Signal',
  10 |   pe:        'Valuation',
  11 |   eps:       'EPS Growth',
  12 |   debt:      'Debt/Eq',
  13 |   margin:    'Margin',
  14 |   rsi_score: 'RSI',
  15 |   short:     'Short Interest',
  16 | };
  17 | 
  18 | // ── localStorage keys ─────────────────────────────────────────────────────
  19 | const LS_THEME     = 'sp_theme';
  20 | const LS_SCORES    = 'sp_score_history';   // { TICKER: [{ts, score}, ...] }
  21 | const LS_PORTFOLIO = 'sp_portfolio';        // { TICKER: sharesCount }
  22 | const LS_ALERTS    = 'sp_alerts';           // { TICKER: {price, score} }
  23 | 
  24 | // ── Theme ─────────────────────────────────────────────────────────────────
  25 | function toggleTheme() {
  26 |   const isLight = document.body.classList.toggle('light');
  27 |   document.getElementById('theme-toggle').textContent = isLight ? '☀' : '☾';
  28 |   localStorage.setItem(LS_THEME, isLight ? 'light' : 'dark');
  29 | }
  30 | 
  31 | function applyStoredTheme() {
  32 |   if (localStorage.getItem(LS_THEME) === 'light') {
  33 |     document.body.classList.add('light');
  34 |     document.getElementById('theme-toggle').textContent = '☀';
  35 |   }
  36 | }
  37 | 
  38 | // ── Boot ──────────────────────────────────────────────────────────────────
  39 | window.addEventListener('DOMContentLoaded', async () => {
  40 |   applyStoredTheme();
  41 |   await loadSectors();
  42 |   await loadStocks();
  43 | });
  44 | 
  45 | // ── Sector dropdown ───────────────────────────────────────────────────────
  46 | async function loadSectors() {
  47 |   try {
  48 |     const res  = await fetch(`${API}/sectors`);
  49 |     const data = await res.json();
  50 |     const sel  = document.getElementById('sector-select');
  51 |     sel.innerHTML = '';
  52 |     data.sectors.forEach(s => {
  53 |       const opt = document.createElement('option');
  54 |       opt.value = s;
  55 |       opt.textContent = s === 'all' ? 'All Sectors' : s;
  56 |       sel.appendChild(opt);
  57 |     });
  58 |   } catch { /* keep default */ }
  59 | }
  60 | 
  61 | // ── Main data loader ──────────────────────────────────────────────────────
  62 | async function loadStocks(force = false) {
  63 |   const sector = document.getElementById('sector-select').value;
  64 |   const mode   = document.getElementById('mode-select').value;
  65 |   const url    = `${API}/top-stocks?sector=${encodeURIComponent(sector)}&mode=${mode}`;
  66 | 
  67 |   // Force-bust the backend cache when explicitly requested
  68 |   if (force) {
  69 |     try { await fetch(`${API}/cache`, { method: 'DELETE' }); } catch (_) {}
  70 |   }
  71 | 
  72 |   showLoading(true);
  73 |   hideBanner();
  74 |   setRefreshSpinning(true);
  75 | 
  76 |   try {
  77 |     const res  = await fetch(url);
  78 |     if (!res.ok) throw new Error(`HTTP ${res.status}`);
  79 |     const data = await res.json();
  80 |     stockData     = data.stocks || [];
  81 |     activeWeights = data.weights || {};
  82 | 
  83 |     // Show timestamp + cache hit ratio
  84 |     const cacheInfo = data.cache;
  85 |     const hitRatio  = cacheInfo
  86 |       ? `${cacheInfo.hits}H / ${cacheInfo.misses}M`
  87 |       : '';
  88 |     const ts = data.generated
  89 |       ? 'Updated ' + new Date(data.generated).toLocaleTimeString()
  90 |         + (hitRatio ? ` · Cache ${hitRatio}` : '')
  91 |       : '';
  92 |     document.getElementById('last-updated').textContent = ts;
  93 | 
  94 |     // Feature 5: persist score history for every fetched ticker
  95 |     persistScoreHistory(stockData);
  96 | 
  97 |     renderWeightBar(activeWeights, data.mode);
  98 |     document.getElementById('cards-grid').innerHTML = '';  // force fresh stagger on new data
  99 |     reRender();
 100 | 
 101 |     // Feature 6: check alerts after data loads
 102 |     checkAlerts(stockData);
 103 | 
 104 |     // Feature 4: refresh portfolio panel if open
 105 |     if (!document.getElementById('portfolio-panel').classList.contains('hidden')) {
 106 |       renderPortfolioPanel();
 107 |     }
 108 |   } catch (err) {
 109 |     showBanner(`⚠️ Could not reach the backend: ${err.message}. Is the Flask server running?`, 'error');
 110 |   } finally {
 111 |     showLoading(false);
 112 |     setRefreshSpinning(false);
 113 |   }
 114 | }
