 116 | // ── Weight pill bar ───────────────────────────────────────────────────────
 117 | function renderWeightBar(weights, mode) {
 118 |   const bar   = document.getElementById('weight-bar');
 119 |   const pills = document.getElementById('weight-pills');
 120 |   if (!weights || !Object.keys(weights).length) {
 121 |     bar.classList.add('hidden');
 122 |     return;
 123 |   }
 124 | 
 125 |   const modeTag  = mode ? ` <span style="color:var(--accent);font-weight:700;">[${mode}]</span>` : '';
 126 |   const maxW     = Math.max(...Object.values(weights));
 127 | 
 128 |   pills.innerHTML = Object.entries(weights).map(([key, val]) => {
 129 |     const pct   = Math.round(val * 100);
 130 |     const barW  = Math.round((val / maxW) * 100);
 131 |     const label = SIGNAL_LABELS[key] || key;
 132 |     return `<span class="weight-pill">
 133 |       <span class="weight-pill-name">${label}</span>
 134 |       <span class="weight-pill-track"><span class="weight-pill-fill" style="width:${barW}%"></span></span>
 135 |       <span class="weight-pill-val">${pct}%</span>
 136 |     </span>`;
 137 |   }).join('');
 138 | 
 139 |   document.querySelector('.weight-bar-label').innerHTML = `🎲 Formula${modeTag}:`;
 140 |   bar.classList.remove('hidden');
 141 | }
 142 | 
 143 | // ── Ticker scramble ───────────────────────────────────────────────────────
 144 | const SCRAMBLE_CHARS = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789#@$%&';
 145 | 
 146 | function scrambleTicker(anchorEl, realTicker) {
 147 |   const len      = realTicker.length;
 148 |   const totalMs  = 1100;          // total duration
 149 |   const frameMs  = 45;            // ms per frame
 150 |   const frames   = Math.round(totalMs / frameMs);
 151 |   // each character resolves after a staggered portion of the total frames
 152 |   const resolveAt = realTicker.split('').map((_, i) =>
 153 |     Math.round(frames * (0.35 + (i / len) * 0.55))
 154 |   );
 155 | 
 156 |   let frame = 0;
 157 |   const iv = setInterval(() => {
 158 |     frame++;
 159 |     const display = realTicker.split('').map((ch, i) => {
 160 |       if (frame >= resolveAt[i]) return ch;
 161 |       return SCRAMBLE_CHARS[Math.floor(Math.random() * SCRAMBLE_CHARS.length)];
 162 |     }).join('');
 163 | 
 164 |     // Keep the ↗ suffix that's part of the link text
 165 |     anchorEl.textContent = display + ' ↗';
 166 | 
 167 |     if (frame >= frames) {
 168 |       clearInterval(iv);
 169 |       anchorEl.textContent = realTicker + ' ↗';
 170 |       anchorEl.classList.remove('scrambling');
 171 |     }
 172 |   }, frameMs);
 173 | 
 174 |   anchorEl.classList.add('scrambling');
 175 | }
 176 | 
 177 | function scrambleRandomCard(grid, sorted) {
 178 |   if (!sorted.length) return;
 179 |   const pick   = sorted[Math.floor(Math.random() * sorted.length)];
 180 |   const card   = grid.querySelector(`[data-ticker="${pick.ticker}"]`);
 181 |   if (!card) return;
 182 |   const anchor = card.querySelector('.row-ticker-sym');
 183 |   if (!anchor) return;
 184 |   scrambleTicker(anchor, pick.ticker);
 185 | }
 186 | 
 187 | // ── Re-render (sort only) ─────────────────────────────────────────────────
 188 | function reRender() {
 189 |   const sortKey = document.getElementById('sort-select').value;
 190 |   const n       = parseInt(document.getElementById('top-n').value, 10);
 191 | 
 192 |   const sorted = [...stockData].sort((a, b) => {
 193 |     if (sortKey === 'score')    return b.score    - a.score;
 194 |     if (sortKey === 'change1d') return b.change1d - a.change1d;
 195 |     if (sortKey === 'pe')       return (a.pe ?? 9999) - (b.pe ?? 9999);
 196 |     if (sortKey === 'rsi')      return (a.rsi ?? 9999) - (b.rsi ?? 9999);
 197 |     return 0;
 198 |   }).slice(0, n);
 199 | 
 200 |   const grid = document.getElementById('cards-grid');
 201 | 
 202 |   // ── First-ever render: build all cards from scratch with stagger ──────────
 203 |   if (grid.children.length === 0) {
 204 |     sorted.forEach((s, i) => {
 205 |       const hue  = Math.round((i / sorted.length) * 360);
 206 |       const card = buildCard(s, i + 1, hue);
 207 |       card.style.animationDelay = `${i * 55}ms`;
 208 |       card.classList.add('card-enter');
 209 |       grid.appendChild(card);
 210 |     });
 211 |     grid.classList.remove('hidden');
 212 |     document.getElementById('table-head').classList.remove('hidden');
 213 |     requestAnimationFrame(() => sorted.forEach(s => drawSparkline(s)));
 214 |     // Scramble a random ticker once the stagger animation settles
 215 |     setTimeout(() => scrambleRandomCard(grid, sorted), sorted.length * 55 + 400);
 216 |     return;
 217 |   }
 218 | 
 219 |   // ── Subsequent renders: FLIP animation ────────────────────────────────────
 220 | 
 221 |   // Build / remove cards for tickers that entered or left the visible set
 222 |   const visibleTickers = new Set(sorted.map(s => s.ticker));
 223 |   const existingTickers = new Set(
 224 |     [...grid.children].map(el => el.dataset.ticker)
 225 |   );
 226 | 
 227 |   // Add new cards (hidden offscreen until positioned)
 228 |   const newTickers = [...visibleTickers].filter(t => !existingTickers.has(t));
 229 |   newTickers.forEach(ticker => {
 230 |     const s    = sorted.find(x => x.ticker === ticker);
 231 |     const i    = sorted.indexOf(s);
 232 |     const hue  = Math.round((i / sorted.length) * 360);
 233 |     const card = buildCard(s, i + 1, hue);
 234 |     card.style.opacity = '0';
 235 |     grid.appendChild(card);
 236 |     drawSparkline(s);
 237 |   });
 238 | 
 239 |   // Remove cards no longer in the visible set
 240 |   [...grid.children].forEach(el => {
 241 |     if (!visibleTickers.has(el.dataset.ticker)) el.remove();
 242 |   });
 243 | 
 244 |   // Update rank labels and hues for every card
 245 |   sorted.forEach((s, i) => {
 246 |     const card = grid.querySelector(`[data-ticker="${s.ticker}"]`);
 247 |     if (!card) return;
 248 |     const hue = Math.round((i / sorted.length) * 360);
 249 |     card.style.setProperty('--card-hue', hue);
 250 |     const medals    = ['🥇','🥈','🥉'];
 251 |     const rankLabel = (i + 1) <= 3 ? medals[i] : `#${i + 1}`;
 252 |     const rankEl    = card.querySelector('.row-rank');
 253 |     if (rankEl) {
 254 |       rankEl.textContent = rankLabel;
 255 |       rankEl.className   = `row-rank${(i + 1) <= 3 ? ' top3' : ''}`;
 256 |     }
 257 |   });
 258 | 
 259 |   // ── FLIP: record positions BEFORE reorder ──────────────────────────────────
 260 |   const first = {};
 261 |   [...grid.children].forEach(el => {
 262 |     first[el.dataset.ticker] = el.getBoundingClientRect().top;
 263 |   });
 264 | 
 265 |   // ── Reorder DOM nodes to match new sort ───────────────────────────────────
 266 |   sorted.forEach(s => {
 267 |     const card = grid.querySelector(`[data-ticker="${s.ticker}"]`);
 268 |     if (card) grid.appendChild(card);   // moves to end; sorted order is preserved
 269 |   });
 270 | 
 271 |   // ── FLIP: compute delta and animate each card ─────────────────────────────
 272 |   sorted.forEach((s, i) => {
 273 |     const card = grid.querySelector(`[data-ticker="${s.ticker}"]`);
 274 |     if (!card) return;
 275 | 
 276 |     const isNew = newTickers.includes(s.ticker);
 277 |     if (isNew) {
 278 |       // New cards fade + slide in
 279 |       card.style.transition = 'none';
 280 |       card.style.transform  = 'translateX(24px)';
 281 |       card.style.opacity    = '0';
 282 |       requestAnimationFrame(() => {
 283 |         card.style.transition = 'transform 0.38s cubic-bezier(0.22,0.61,0.36,1), opacity 0.3s ease';
 284 |         card.style.transform  = '';
 285 |         card.style.opacity    = '';
 286 |       });
 287 |       return;
 288 |     }
 289 | 
 290 |     const last  = card.getBoundingClientRect().top;
 291 |     const delta = first[s.ticker] - last;
 292 | 
 293 |     if (Math.abs(delta) < 1) return;  // already in place — skip
 294 | 
 295 |     // Snap card back to where it was (visually), then animate to final spot
 296 |     card.style.transition = 'none';
 297 |     card.style.transform  = `translateY(${delta}px)`;
