 820 | // ── Floating button physics ────────────────────────────────────────────────
 821 | let _floatX = 0, _floatY = 0;       // current position (px)
 822 | let _floatVX = 2.2, _floatVY = 1.7; // velocity (px per frame)
 823 | let _floatAngle = 0;                 // current rotation (deg)
 824 | let _floatSpin  = 1.8;               // rotation speed (deg per frame)
 825 | let _floatT     = 0;                 // time counter for opacity sine wave
 826 | let _floatRafId  = null;
 827 | let _floatPaused = false;
 828 | 
 829 | function _floatLoop() {
 830 |   const btn = document.getElementById('random-ticker-btn');
 831 |   if (!btn) return;
 832 | 
 833 |   if (!_floatPaused) {
 834 |     const bw = btn.offsetWidth  || 90;
 835 |     const bh = btn.offsetHeight || 26;
 836 |     const maxX = window.innerWidth  - bw;
 837 |     const maxY = window.innerHeight - bh;
 838 | 
 839 |     _floatX += _floatVX;
 840 |     _floatY += _floatVY;
 841 | 
 842 |     // Bounce off edges
 843 |     if (_floatX <= 0)    { _floatX = 0;    _floatVX = Math.abs(_floatVX); }
 844 |     if (_floatX >= maxX) { _floatX = maxX; _floatVX = -Math.abs(_floatVX); }
 845 |     if (_floatY <= 0)    { _floatY = 0;    _floatVY = Math.abs(_floatVY); }
 846 |     if (_floatY >= maxY) { _floatY = maxY; _floatVY = -Math.abs(_floatVY); }
 847 | 
 848 |     _floatAngle += _floatSpin;
 849 |     _floatT     += 0.025;  // sine wave speed — lower = slower fade
 850 | 
 851 |     const opacity = 0.3 + 0.7 * (Math.sin(_floatT) * 0.5 + 0.5);
 852 | 
 853 |     btn.style.left      = _floatX + 'px';
 854 |     btn.style.top       = _floatY + 'px';
 855 |     btn.style.transform = `rotate(${_floatAngle}deg)`;
 856 |     btn.style.opacity   = opacity;
 857 |   }
 858 | 
 859 |   _floatRafId = requestAnimationFrame(_floatLoop);
 860 | }
 861 | 
 862 | // Randomly pause for 0.8–2.5 s, then resume in a new direction; repeats every 4–10 s
 863 | function _scheduleNextPause() {
 864 |   const delay    = 4000 + Math.random() * 6000;   // wait 4–10 s before pausing
 865 |   const duration = 800  + Math.random() * 1700;   // stay paused 0.8–2.5 s
 866 |   setTimeout(() => {
 867 |     _floatPaused = true;
 868 |     setTimeout(() => {
 869 |       // Pick a fresh random direction at the same speed
 870 | 
 871 |       const angle = Math.random() * 2 * Math.PI;
 872 |       const speed = 2.5;
 873 |       _floatVX = Math.cos(angle) * speed;
 874 |       _floatVY = Math.sin(angle) * speed;
 875 |       // Pick a new random spin speed (1–3 deg/frame, random direction)
 876 |       _floatSpin = (1 + Math.random() * 2) * (Math.random() < 0.5 ? 1 : -1);
 877 |       _floatPaused = false;
 878 |       _scheduleNextPause();
 879 |     }, duration);
 880 |   }, delay);
 881 | }
