326 |   const chgClass   = s.change1d > 0 ? 'pos' : s.change1d < 0 ? 'neg' : 'neu';
327 |   const chgSign    = s.change1d > 0 ? '+' : '';
328 |   const medals     = ['🥇','🥈','🥉'];
329 |   const rankLabel  = rank <= 3 ? medals[rank - 1] : `#${rank}`;
330 | 
331 |   card.innerHTML = `
