1145 | // ── Synthesised laugh track via Web Audio API ─────────────────────────────
1146 | function playLaughTrack() {
1147 |   let ctx;
1148 |   try {
1149 |     ctx = new (window.AudioContext || window.webkitAudioContext)();
1150 |   } catch (_) { return; } // browser doesn't support Web Audio — silently skip
1151 | 
1152 |   // Master gain so we can fade the whole laugh out at the end
1153 |   const master = ctx.createGain();
1154 |   master.gain.setValueAtTime(0.55, ctx.currentTime);
1155 |   master.gain.linearRampToValueAtTime(0, ctx.currentTime + 2.4);
1156 |   master.connect(ctx.destination);
1157 | 
1158 |   // Each "laugh voice" is a short burst of descending tones
1159 |   // We layer several voices with different timings & pitches for a crowd feel
1160 |   const voices = [
1161 |     { baseFreq: 420, offset: 0.00, count: 5, speed: 0.13, vol: 0.55 },
1162 |     { baseFreq: 370, offset: 0.05, count: 6, speed: 0.12, vol: 0.45 },
1163 |     { baseFreq: 500, offset: 0.02, count: 4, speed: 0.15, vol: 0.35 },
1164 |     { baseFreq: 340, offset: 0.08, count: 5, speed: 0.11, vol: 0.40 },
1165 |     { baseFreq: 460, offset: 0.03, count: 6, speed: 0.14, vol: 0.30 },
1166 |     { baseFreq: 390, offset: 0.11, count: 4, speed: 0.13, vol: 0.38 },
1167 |   ];
1168 | 
1169 |   voices.forEach(({ baseFreq, offset, count, speed, vol }) => {
1170 |     for (let i = 0; i < count; i++) {
1171 |       const t = ctx.currentTime + offset + i * speed;
1172 | 
1173 |       // Each "ha" = a quick pitch-bend from high → low (the "ha" shape)
1174 |       const osc  = ctx.createOscillator();
1175 |       const gain = ctx.createGain();
1176 | 
1177 |       osc.type = 'sine';
1178 |       // Slight random variation so voices don't sound identical
1179 |       const freq = baseFreq * (1 + (Math.random() - 0.5) * 0.12);
1180 |       osc.frequency.setValueAtTime(freq * 1.18, t);
1181 |       osc.frequency.exponentialRampToValueAtTime(freq * 0.72, t + 0.09);
1182 | 
1183 |       // Attack → short sustain → decay envelope
1184 |       gain.gain.setValueAtTime(0, t);
1185 |       gain.gain.linearRampToValueAtTime(vol, t + 0.018);
1186 |       gain.gain.setValueAtTime(vol,       t + 0.055);
1187 |       gain.gain.exponentialRampToValueAtTime(0.001, t + 0.115);
1188 | 
1189 |       osc.connect(gain);
1190 |       gain.connect(master);
1191 |       osc.start(t);
1192 |       osc.stop(t + 0.13);
1193 | 
1194 |       // Add a subtle overtone (2nd harmonic) for a more "vocal" texture
1195 |       const osc2  = ctx.createOscillator();
1196 |       const gain2 = ctx.createGain();
1197 |       osc2.type = 'triangle';
1198 |       osc2.frequency.setValueAtTime(freq * 2.2, t);
1199 |       osc2.frequency.exponentialRampToValueAtTime(freq * 1.4, t + 0.09);
1200 |       gain2.gain.setValueAtTime(0, t);
1201 |       gain2.gain.linearRampToValueAtTime(vol * 0.22, t + 0.018);
1202 |       gain2.gain.exponentialRampToValueAtTime(0.001, t + 0.10);
1203 |       osc2.connect(gain2);
1204 |       gain2.connect(master);
1205 |       osc2.start(t);
1206 |       osc2.stop(t + 0.12);
1207 |     }
1208 |   });
1209 | 
1210 |   // Auto-close the AudioContext after the laugh finishes
1211 |   setTimeout(() => { try { ctx.close(); } catch (_) {} }, 2600);
1212 | }
