688 | function updatePortfolioSummary() {
689 |   const portfolio = loadPortfolio();
690 |   const summaryEl = document.getElementById('portfolio-summary');
691 |   const held      = stockData.filter(s => portfolio[s.ticker] > 0);
692 | 
693 |   if (held.length === 0) { summaryEl.classList.add('hidden'); return; }
694 |   summaryEl.classList.remove('hidden');
695 | 
696 |   let totalValue = 0, totalDayPnl = 0, weightedScore = 0;
697 |   held.forEach(s => {
698 |     const shares    = portfolio[s.ticker];
699 |     const val       = shares * s.currentPrice;
700 |     const prevPrice = s.currentPrice / (1 + s.change1d / 100);
701 |     totalValue    += val;
702 |     totalDayPnl   += shares * (s.currentPrice - prevPrice);
703 |     weightedScore += s.score * val;
704 |   });
705 | 
706 |   const avgScore = totalValue > 0 ? (weightedScore / totalValue).toFixed(1) : '—';
707 |   const pnlSign  = totalDayPnl >= 0 ? '+' : '';
708 |   const pnlClass = totalDayPnl >= 0 ? 'pos' : 'neg';
709 | 
710 |   document.getElementById('port-total-value').textContent =
711 |     '$' + totalValue.toLocaleString('en-US',{minimumFractionDigits:2,maximumFractionDigits:2});
712 |   document.getElementById('port-daily-pnl').innerHTML =
713 |     `<span class="chg ${pnlClass}">${pnlSign}$${Math.abs(totalDayPnl).toLocaleString('en-US',{minimumFractionDigits:2,maximumFractionDigits:2})}</span>`;
714 |   document.getElementById('port-avg-score').textContent = avgScore;
715 | }
