255 |       rankEl.className   = `row-rank${(i + 1) <= 3 ? ' top3' : ''}`;
256 |     }
257 |   });
258 | 
259 |   // ── FLIP: record positions BEFORE reorder ──────────────────────────────────
260 |   const first = {};
261 |   [...grid.children].forEach(el => {
262 |     first[el.dataset.ticker] = el.getBoundingClientRect().top;
263 |   });
264 | 
265 |   // ── Reorder DOM nodes to match new sort ───────────────────────────────────
266 |   sorted.forEach(s => {
267 |     const card = grid.querySelector(`[data-ticker="${s.ticker}"]`);
268 |     if (card) grid.appendChild(card);   // moves to end; sorted order is preserved
269 |   });
270 | 
271 |   // ── FLIP: compute delta and animate each card ─────────────────────────────
272 |   sorted.forEach((s, i) => {
273 |     const card = grid.querySelector(`[data-ticker="${s.ticker}"]`);
274 |     if (!card) return;
275 | 
276 |     const isNew = newTickers.includes(s.ticker);
