1244 | // ── Synthesised laugh track via Web Audio API ─────────────────────────────
1245 | function playLaughTrack() {
1246 |   let ctx;
1247 |   try {
1248 |     ctx = new (window.AudioContext || window.webkitAudioContext)();
1249 |   } catch (_) { return; } // browser doesn't support Web Audio — silently skip
1250 | 
1251 |   // Master gain so we can fade the whole laugh out at the end
1252 |   const master = ctx.createGain();
1253 |   master.gain.setValueAtTime(0.55, ctx.currentTime);
1254 |   master.gain.linearRampToValueAtTime(0, ctx.currentTime + 2.4);
1255 |   master.connect(ctx.destination);
1256 | 
1257 |   // Each "laugh voice" is a short burst of descending tones
1258 |   // We layer several voices with different timings & pitches for a crowd feel
1259 |   const voices = [
1260 |     { baseFreq: 420, offset: 0.00, count: 5, speed: 0.13, vol: 0.55 },
1261 |     { baseFreq: 370, offset: 0.05, count: 6, speed: 0.12, vol: 0.45 },
1262 |     { baseFreq: 500, offset: 0.02, count: 4, speed: 0.15, vol: 0.35 },
1263 |     { baseFreq: 340, offset: 0.08, count: 5, speed: 0.11, vol: 0.40 },
1264 |     { baseFreq: 460, offset: 0.03, count: 6, speed: 0.14, vol: 0.30 },
1265 |     { baseFreq: 390, offset: 0.11, count: 4, speed: 0.13, vol: 0.38 },
1266 |   ];
1267 | 
1268 |   voices.forEach(({ baseFreq, offset, count, speed, vol }) => {
1269 |     for (let i = 0; i < count; i++) {
1270 |       const t = ctx.currentTime + offset + i * speed;
1271 | 
1272 |       // Each "ha" = a quick pitch-bend from high → low (the "ha" shape)
1273 |       const osc  = ctx.createOscillator();
1274 |       const gain = ctx.createGain();
1275 | 
1276 |       osc.type = 'sine';
1277 |       // Slight random variation so voices don't sound identical
1278 |       const freq = baseFreq * (1 + (Math.random() - 0.5) * 0.12);
1279 |       osc.frequency.setValueAtTime(freq * 1.18, t);
1280 |       osc.frequency.exponentialRampToValueAtTime(freq * 0.72, t + 0.09);
1281 | 
1282 |       // Attack → short sustain → decay envelope
1283 |       gain.gain.setValueAtTime(0, t);
1284 |       gain.gain.linearRampToValueAtTime(vol, t + 0.018);
1285 |       gain.gain.setValueAtTime(vol,       t + 0.055);
1286 |       gain.gain.exponentialRampToValueAtTime(0.001, t + 0.115);
1287 | 
1288 |       osc.connect(gain);
1289 |       gain.connect(master);
1290 |       osc.start(t);
1291 |       osc.stop(t + 0.13);
1292 | 
1293 |       // Add a subtle overtone (2nd harmonic) for a more "vocal" texture
1294 |       const osc2  = ctx.createOscillator();
1295 |       const gain2 = ctx.createGain();
1296 |       osc2.type = 'triangle';
1297 |       osc2.frequency.setValueAtTime(freq * 2.2, t);
1298 |       osc2.frequency.exponentialRampToValueAtTime(freq * 1.4, t + 0.09);
1299 |       gain2.gain.setValueAtTime(0, t);
1300 |       gain2.gain.linearRampToValueAtTime(vol * 0.22, t + 0.018);
1301 |       gain2.gain.exponentialRampToValueAtTime(0.001, t + 0.10);
1302 |       osc2.connect(gain2);
1303 |       gain2.connect(master);
1304 |       osc2.start(t);
1305 |       osc2.stop(t + 0.12);
1306 |     }
1307 |   });
1308 | 
1309 |   // Auto-close the AudioContext after the laugh finishes
1310 |   setTimeout(() => { try { ctx.close(); } catch (_) {} }, 2600);
1311 | }
