 194 | // ── Re-render (sort only) ─────────────────────────────────────────────────
 195 | function reRender() {
 196 |   const sortKey = document.getElementById('sort-select').value;
 197 |   const n       = parseInt(document.getElementById('top-n').value, 10);
 198 | 
 199 |   const sorted = [...stockData].sort((a, b) => {
 200 |     if (sortKey === 'score')    return b.score    - a.score;
 201 |     if (sortKey === 'change1d') return b.change1d - a.change1d;
 202 |     if (sortKey === 'pe')       return (a.pe ?? 9999) - (b.pe ?? 9999);
 203 |     if (sortKey === 'rsi')      return (a.rsi ?? 9999) - (b.rsi ?? 9999);
 204 |     return 0;
 205 |   }).slice(0, n);
 206 | 
 207 |   const grid = document.getElementById('cards-grid');
 208 | 
 209 |   // ── First-ever render: build all cards from scratch with stagger ──────────
 210 |   if (grid.children.length === 0) {
 211 |     sorted.forEach((s, i) => {
 212 |       const hue  = Math.round((i / sorted.length) * 360);
 213 |       const card = buildCard(s, i + 1, hue);
 214 |       card.style.animationDelay = `${i * 55}ms`;
 215 |       card.classList.add('card-enter');
 216 |       grid.appendChild(card);
 217 |     });
 218 |     grid.classList.remove('hidden');
 219 |     document.getElementById('table-head').classList.remove('hidden');
 220 |     requestAnimationFrame(() => sorted.forEach(s => drawSparkline(s)));
 221 |     // Scramble a random ticker once the stagger animation settles
 222 |     setTimeout(() => scrambleRandomCard(grid, sorted), sorted.length * 55 + 400);
 223 |     return;
 224 |   }
 225 | 
 226 |   // ── Subsequent renders: FLIP animation ────────────────────────────────────
 227 | 
 228 |   // Build / remove cards for tickers that entered or left the visible set
 229 |   const visibleTickers = new Set(sorted.map(s => s.ticker));
 230 |   const existingTickers = new Set(
 231 |     [...grid.children].map(el => el.dataset.ticker)
 232 |   );
 233 | 
 234 |   // Add new cards (hidden offscreen until positioned)
 235 |   const newTickers = [...visibleTickers].filter(t => !existingTickers.has(t));
 236 |   newTickers.forEach(ticker => {
 237 |     const s    = sorted.find(x => x.ticker === ticker);
 238 |     const i    = sorted.indexOf(s);
 239 |     const hue  = Math.round((i / sorted.length) * 360);
 240 |     const card = buildCard(s, i + 1, hue);
 241 |     card.style.opacity = '0';
 242 |     grid.appendChild(card);
 243 |     drawSparkline(s);
 244 |   });
 245 | 
 246 |   // Remove cards no longer in the visible set
 247 |   [...grid.children].forEach(el => {
 248 |     if (!visibleTickers.has(el.dataset.ticker)) el.remove();
 249 |   });
 250 | 
 251 |   // Update rank labels and hues for every card
 252 |   sorted.forEach((s, i) => {
 253 |     const card = grid.querySelector(`[data-ticker="${s.ticker}"]`);
 254 |     if (!card) return;
 255 |     const hue = Math.round((i / sorted.length) * 360);
 256 |     card.style.setProperty('--card-hue', hue);
 257 |     const medals    = ['🥇','🥈','🥉'];
 258 |     const rankLabel = (i + 1) <= 3 ? medals[i] : `#${i + 1}`;
 259 |     const rankEl    = card.querySelector('.row-rank');
 260 |     if (rankEl) {
 261 |       rankEl.textContent = rankLabel;
 262 |       rankEl.className   = `row-rank${(i + 1) <= 3 ? ' top3' : ''}`;
 263 |     }
 264 |   });
 265 | 
 266 |   // ── FLIP: record positions BEFORE reorder ──────────────────────────────────
 267 |   const first = {};
 268 |   [...grid.children].forEach(el => {
 269 |     first[el.dataset.ticker] = el.getBoundingClientRect().top;
 270 |   });
 271 | 
 272 |   // ── Reorder DOM nodes to match new sort ───────────────────────────────────
 273 |   sorted.forEach(s => {
 274 |     const card = grid.querySelector(`[data-ticker="${s.ticker}"]`);
 275 |     if (card) grid.appendChild(card);   // moves to end; sorted order is preserved
 276 |   });
 277 | 
 278 |   // ── FLIP: compute delta and animate each card ─────────────────────────────
 279 |   sorted.forEach((s, i) => {
 280 |     const card = grid.querySelector(`[data-ticker="${s.ticker}"]`);
 281 |     if (!card) return;
 282 | 
 283 |     const isNew = newTickers.includes(s.ticker);
 284 |     if (isNew) {
 285 |       // New cards fade + slide in
 286 |       card.style.transition = 'none';
 287 |       card.style.transform  = 'translateX(24px)';
 288 |       card.style.opacity    = '0';
 289 |       requestAnimationFrame(() => {
 290 |         card.style.transition = 'transform 0.38s cubic-bezier(0.22,0.61,0.36,1), opacity 0.3s ease';
 291 |         card.style.transform  = '';
 292 |         card.style.opacity    = '';
 293 |       });
 294 |       return;
 295 |     }
 296 | 
 297 |     const last  = card.getBoundingClientRect().top;
 298 |     const delta = first[s.ticker] - last;
 299 | 
 300 |     if (Math.abs(delta) < 1) return;  // already in place — skip
 301 | 
 302 |     // Snap card back to where it was (visually), then animate to final spot
 303 |     card.style.transition = 'none';
 304 |     card.style.transform  = `translateY(${delta}px)`;
 305 | 
 306 |     requestAnimationFrame(() => {
 307 |       requestAnimationFrame(() => {
 308 |         card.style.transition = 'transform 0.42s cubic-bezier(0.22,0.61,0.36,1)';
 309 |         card.style.transform  = '';
 310 |       });
 311 |     });
 312 |   });
 313 | 
 314 |   // Scramble a random ticker after the FLIP moves settle
 315 |   setTimeout(() => scrambleRandomCard(grid, sorted), 500);
 316 | }
