 528 | /** Save the current score for each ticker with a UTC timestamp. */
 529 | function persistScoreHistory(stocks) {
 530 |   let history = {};
 531 |   try { history = JSON.parse(localStorage.getItem(LS_SCORES) || '{}'); } catch {}
 532 |   const ts = Date.now();
 533 |   stocks.forEach(s => {
 534 |     if (!history[s.ticker]) history[s.ticker] = [];
 535 |     // Only append if the last entry was > 5 minutes ago (avoid duplicates on rapid refresh)
 536 |     const last = history[s.ticker].at(-1);
 537 |     if (!last || ts - last.ts > 5 * 60 * 1000) {
 538 |       history[s.ticker].push({ ts, score: s.score });
 539 |     }
 540 |     // Keep only the last 60 data points per ticker
 541 |     if (history[s.ticker].length > 60) history[s.ticker] = history[s.ticker].slice(-60);
 542 |   });
 543 |   try { localStorage.setItem(LS_SCORES, JSON.stringify(history)); } catch {}
 544 | }
