 870 | function _scheduleNextPause() {
 871 |   const delay    = 4000 + Math.random() * 6000;   // wait 4–10 s before pausing
 872 |   const duration = 800  + Math.random() * 1700;   // stay paused 0.8–2.5 s
 873 |   setTimeout(() => {
 874 |     _floatPaused = true;
 875 |     setTimeout(() => {
 876 |       // Pick a fresh random direction at the same speed
 877 | 
 878 |       const angle = Math.random() * 2 * Math.PI;
 879 |       const speed = 2.5;
 880 |       _floatVX = Math.cos(angle) * speed;
 881 |       _floatVY = Math.sin(angle) * speed;
 882 |       // Pick a new random spin speed (1–3 deg/frame, random direction)
 883 |       _floatSpin = (1 + Math.random() * 2) * (Math.random() < 0.5 ? 1 : -1);
 884 |       _floatPaused = false;
 885 |       _scheduleNextPause();
 886 |     }, duration);
 887 |   }, delay);
