1424 | // ── Synthesised laugh track via Web Audio API ─────────────────────────────
1425 | function playLaughTrack() {
1426 |   let ctx;
1427 |   try {
1428 |     ctx = new (window.AudioContext || window.webkitAudioContext)();
1429 |   } catch (_) { return; } // browser doesn't support Web Audio — silently skip
1430 | 
1431 |   // Master gain so we can fade the whole laugh out at the end
1432 |   const master = ctx.createGain();
1433 |   master.gain.setValueAtTime(0.55, ctx.currentTime);
1434 |   master.gain.linearRampToValueAtTime(0, ctx.currentTime + 2.4);
1435 |   master.connect(ctx.destination);
1436 | 
1437 |   // Each "laugh voice" is a short burst of descending tones
1438 |   // We layer several voices with different timings & pitches for a crowd feel
1439 |   const voices = [
1440 |     { baseFreq: 420, offset: 0.00, count: 5, speed: 0.13, vol: 0.55 },
1441 |     { baseFreq: 370, offset: 0.05, count: 6, speed: 0.12, vol: 0.45 },
1442 |     { baseFreq: 500, offset: 0.02, count: 4, speed: 0.15, vol: 0.35 },
1443 |     { baseFreq: 340, offset: 0.08, count: 5, speed: 0.11, vol: 0.40 },
1444 |     { baseFreq: 460, offset: 0.03, count: 6, speed: 0.14, vol: 0.30 },
1445 |     { baseFreq: 390, offset: 0.11, count: 4, speed: 0.13, vol: 0.38 },
1446 |   ];
1447 | 
1448 |   voices.forEach(({ baseFreq, offset, count, speed, vol }) => {
1449 |     for (let i = 0; i < count; i++) {
1450 |       const t = ctx.currentTime + offset + i * speed;
1451 | 
1452 |       // Each "ha" = a quick pitch-bend from high → low (the "ha" shape)
1453 |       const osc  = ctx.createOscillator();
1454 |       const gain = ctx.createGain();
1455 | 
1456 |       osc.type = 'sine';
1457 |       // Slight random variation so voices don't sound identical
1458 |       const freq = baseFreq * (1 + (Math.random() - 0.5) * 0.12);
1459 |       osc.frequency.setValueAtTime(freq * 1.18, t);
1460 |       osc.frequency.exponentialRampToValueAtTime(freq * 0.72, t + 0.09);
1461 | 
1462 |       // Attack → short sustain → decay envelope
1463 |       gain.gain.setValueAtTime(0, t);
1464 |       gain.gain.linearRampToValueAtTime(vol, t + 0.018);
1465 |       gain.gain.setValueAtTime(vol,       t + 0.055);
1466 |       gain.gain.exponentialRampToValueAtTime(0.001, t + 0.115);
1467 | 
1468 |       osc.connect(gain);
1469 |       gain.connect(master);
1470 |       osc.start(t);
1471 |       osc.stop(t + 0.13);
1472 | 
1473 |       // Add a subtle overtone (2nd harmonic) for a more "vocal" texture
1474 |       const osc2  = ctx.createOscillator();
1475 |       const gain2 = ctx.createGain();
1476 |       osc2.type = 'triangle';
1477 |       osc2.frequency.setValueAtTime(freq * 2.2, t);
1478 |       osc2.frequency.exponentialRampToValueAtTime(freq * 1.4, t + 0.09);
1479 |       gain2.gain.setValueAtTime(0, t);
1480 |       gain2.gain.linearRampToValueAtTime(vol * 0.22, t + 0.018);
1481 |       gain2.gain.exponentialRampToValueAtTime(0.001, t + 0.10);
1482 |       osc2.connect(gain2);
1483 |       gain2.connect(master);
1484 |       osc2.start(t);
1485 |       osc2.stop(t + 0.12);
1486 |     }
1487 |   });
1488 | 
1489 |   // Auto-close the AudioContext after the laugh finishes
1490 |   setTimeout(() => { try { ctx.close(); } catch (_) {} }, 2600);
1491 | }
