// ── Alert panel injection: append to detail modal after open ─────────────
// Patches the modal DOM directly so we don't need to touch the openModal template.
document.addEventListener('click', function _alertPanelInjector(e) {
  // Wait for the next tick so modal content is fully rendered
  const overlay = document.getElementById('modal-overlay');
  if (!overlay || overlay.classList.contains('hidden')) return;
  // Only inject once per open (guard via data attribute)
  const content = document.getElementById('modal-content');
  if (!content || content.querySelector('.set-alert-panel')) return;

  // Pull ticker from the modal's first element with class .modal-ticker
  const tickerEl = content.querySelector('.modal-ticker');
  if (!tickerEl) return;
  const ticker = tickerEl.textContent.trim();

  // Find currentPrice from the .modal-price element
  const priceText = content.querySelector('.modal-price');
  let price = 0;
  if (priceText) {
    const m = priceText.textContent.match(/\$([\d,.]+)/);
    if (m) price = parseFloat(m[1].replace(',', ''));
  }

  const div = document.createElement('div');
  div.innerHTML = renderSetAlertPanel(ticker, price);
  content.appendChild(div.firstElementChild);
}, true);

