/* ── Alert Bell button ── */
.btn-bell {
  background: var(--bg3);
  color: var(--text);
  border: 1px solid var(--border);
  padding: 4px 9px;
  font-size: .9rem;
  position: relative;
}
.btn-bell:hover { border-color: var(--gold); }

.alert-bell-badge {
  position: absolute;
  top: -5px;
  right: -5px;
  background: var(--red);
  color: #fff;
  font-size: .55rem;
  font-weight: 700;
  min-width: 15px;
  height: 15px;
  border-radius: 8px;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 0 3px;
  pointer-events: none;
}

.alert-active-count {
  font-size: .65rem;
  font-weight: 600;
  color: var(--green);
  background: rgba(63,185,80,.12);
  padding: 2px 7px;
  border-radius: 10px;
}

/* ── Alerts modal ── */
.alerts-permission-banner {
  background: rgba(248,81,73,.1);
  border: 1px solid rgba(248,81,73,.3);
  border-radius: 6px;
  padding: 8px 12px;
  font-size: .78rem;
  color: var(--red);
  margin-bottom: 12px;
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 6px;
}

.alerts-empty {
  text-align: center;
  padding: 24px 0;
  color: var(--muted);
  font-size: .8rem;
}

/* Alert list rows */
.alert-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  padding: 9px 12px;
  border-radius: 7px;
  border: 1px solid var(--border);
  background: var(--bg3);
  margin-bottom: 6px;
  transition: border-color .15s;
}
.alert-row:hover { border-color: var(--accent); }
.alert-row.fired { opacity: .65; }

.alert-row-left {
  display: flex;
  align-items: center;
  gap: 10px;
  flex: 1;
  min-width: 0;
  flex-wrap: wrap;
}
.alert-row-right {
  display: flex;
  align-items: center;
  gap: 6px;
  flex-shrink: 0;
}

.alert-row-ticker {
  font-weight: 700;
  color: var(--accent);
  font-size: .82rem;
  min-width: 42px;
}
.alert-row-cond {
  font-size: .78rem;
  color: var(--text);
  white-space: nowrap;
}
.alert-row-date {
  font-size: .7rem;
  color: var(--muted);
}

.alert-row-badge {
  font-size: .62rem;
  font-weight: 700;
  padding: 2px 7px;
  border-radius: 20px;
  text-transform: uppercase;
  letter-spacing: .04em;
  white-space: nowrap;
}
.alert-row-badge.active { background: rgba(63,185,80,.15);  color: var(--green); }
.alert-row-badge.fired  { background: rgba(248,81,73,.12);  color: var(--red); }

.alert-row-btn {
  border: 1px solid var(--border);
  background: var(--bg2);
  color: var(--text);
  border-radius: 5px;
  padding: 2px 8px;
  font-size: .72rem;
  cursor: pointer;
  transition: background .12s, border-color .12s;
  white-space: nowrap;
}
.alert-row-btn:hover { background: var(--bg3); border-color: var(--accent); }
.alert-row-btn.danger { color: var(--red); border-color: rgba(248,81,73,.35); }
.alert-row-btn.danger:hover { background: rgba(248,81,73,.1); border-color: var(--red); }

/* ── Set Alert panel (inside detail modal) ── */
.set-alert-panel {
  margin-top: 16px;
  padding: 12px 14px;
  border-radius: 8px;
  border: 1px solid var(--border);
  background: var(--bg2);
}
.set-alert-title {
  font-size: .8rem;
  font-weight: 700;
  margin-bottom: 9px;
  color: var(--text);
}
.set-alert-row {
  display: flex;
  align-items: center;
  gap: 7px;
  flex-wrap: wrap;
}
.alert-select {
  background: var(--bg3);
  border: 1px solid var(--border);
  color: var(--text);
  border-radius: 5px;
  padding: 3px 7px;
  font-size: .75rem;
  height: 28px;
  cursor: pointer;
  flex: 1;
  min-width: 140px;
}
.alert-select:focus { outline: none; border-color: var(--accent); }
.alert-value-input {
  background: var(--bg3);
  border: 1px solid var(--border);
  color: var(--text);
  border-radius: 5px;
  padding: 3px 7px;
  font-size: .78rem;
  height: 28px;
  width: 90px;
}
.alert-value-input:focus { outline: none; border-color: var(--accent); }
.alert-feedback {
  margin-top: 7px;
  font-size: .75rem;
  color: var(--green);
  padding: 4px 0;
}

