 357 | // ── Sparkline (pure canvas, compact 36 px tall) ───────────────────────────
 358 | function drawSparkline(s) {
 359 |   const canvas = document.getElementById(`spark-${s.ticker}`);
 360 |   if (!canvas || !s.sparkline || s.sparkline.length < 2) return;
 361 | 
 362 |   const dpr = window.devicePixelRatio || 1;
 363 |   const w   = canvas.parentElement.clientWidth - 8; // subtract padding
 364 |   const h   = 36;
 365 |   canvas.width  = w * dpr;
 366 |   canvas.height = h * dpr;
 367 |   canvas.style.width  = w + 'px';
 368 |   canvas.style.height = h + 'px';
 369 |   const ctx = canvas.getContext('2d');
 370 |   ctx.scale(dpr, dpr);
 371 | 
 372 |   const prices = s.sparkline;
 373 |   const min    = Math.min(...prices);
 374 |   const max    = Math.max(...prices);
 375 |   const range  = max - min || 1;
 376 |   const pad    = 2;
 377 |   const xFn    = i => (i / (prices.length - 1)) * (w - pad * 2) + pad;
 378 |   const yFn    = v => h - pad - ((v - min) / range) * (h - pad * 2);
 379 | 
 380 |   const isUp = prices[prices.length - 1] >= prices[0];
 381 |   const col  = isUp ? '63,185,80' : '248,81,73';
 382 |   const grad = ctx.createLinearGradient(0, 0, 0, h);
 383 |   grad.addColorStop(0, `rgba(${col},.25)`);
 384 |   grad.addColorStop(1, `rgba(${col},0)`);
 385 | 
 386 |   // filled area
 387 |   ctx.beginPath();
 388 |   ctx.moveTo(xFn(0), yFn(prices[0]));
 389 |   prices.forEach((p, i) => { if (i > 0) ctx.lineTo(xFn(i), yFn(p)); });
 390 |   ctx.lineTo(xFn(prices.length - 1), h);
 391 |   ctx.lineTo(xFn(0), h);
 392 |   ctx.closePath();
 393 |   ctx.fillStyle = grad;
 394 |   ctx.fill();
 395 | 
 396 |   // line
 397 |   ctx.beginPath();
 398 |   ctx.moveTo(xFn(0), yFn(prices[0]));
 399 |   prices.forEach((p, i) => { if (i > 0) ctx.lineTo(xFn(i), yFn(p)); });
 400 |   ctx.strokeStyle = `rgb(${col})`;
 401 |   ctx.lineWidth   = 1.5;
 402 |   ctx.lineJoin    = 'round';
 403 |   ctx.stroke();
 404 | }
