 546 | /** Draw a compact line chart of score-over-time onto #score-history-canvas. */
 547 | function drawScoreHistoryChart(ticker) {
 548 |   let history = {};
 549 |   try { history = JSON.parse(localStorage.getItem(LS_SCORES) || '{}'); } catch {}
 550 |   const points = history[ticker] || [];
 551 | 
 552 |   const canvas  = document.getElementById('score-history-canvas');
 553 |   const emptyEl = document.getElementById('score-history-empty');
 554 |   if (!canvas) return;
 555 | 
 556 |   if (points.length < 2) {
 557 |     canvas.style.display = 'none';
 558 |     emptyEl && emptyEl.classList.remove('hidden');
 559 |     return;
 560 |   }
 561 |   emptyEl && emptyEl.classList.add('hidden');
 562 |   canvas.style.display = 'block';
 563 | 
 564 |   const dpr = window.devicePixelRatio || 1;
 565 |   const W   = canvas.parentElement.clientWidth || 400;
 566 |   const H   = 80;
 567 |   canvas.width  = W * dpr;
 568 |   canvas.height = H * dpr;
 569 |   canvas.style.width  = W + 'px';
 570 |   canvas.style.height = H + 'px';
 571 | 
 572 |   const ctx = canvas.getContext('2d');
 573 |   ctx.scale(dpr, dpr);
 574 | 
 575 |   const scores = points.map(p => p.score);
 576 |   const minS   = Math.min(...scores);
 577 |   const maxS   = Math.max(...scores);
 578 |   const range  = Math.max(maxS - minS, 5);
 579 |   const pad    = { t: 6, b: 18, l: 6, r: 6 };
 580 |   const iW     = W - pad.l - pad.r;
 581 |   const iH     = H - pad.t - pad.b;
 582 | 
 583 |   const xFn = i => pad.l + (i / (points.length - 1)) * iW;
 584 |   const yFn = v => pad.t + iH - ((v - minS) / range) * iH;
 585 | 
 586 |   ctx.fillStyle = '#21262d';
 587 |   ctx.fillRect(0, 0, W, H);
 588 | 
 589 |   const grad = ctx.createLinearGradient(0, pad.t, 0, pad.t + iH);
 590 |   grad.addColorStop(0, 'rgba(88,166,255,0.35)');
 591 |   grad.addColorStop(1, 'rgba(88,166,255,0.02)');
 592 |   ctx.beginPath();
 593 |   ctx.moveTo(xFn(0), yFn(scores[0]));
 594 |   scores.forEach((v, i) => { if (i > 0) ctx.lineTo(xFn(i), yFn(v)); });
 595 |   ctx.lineTo(xFn(scores.length - 1), pad.t + iH);
 596 |   ctx.lineTo(xFn(0), pad.t + iH);
 597 |   ctx.closePath();
 598 |   ctx.fillStyle = grad;
 599 |   ctx.fill();
 600 | 
 601 |   ctx.beginPath();
 602 |   ctx.moveTo(xFn(0), yFn(scores[0]));
 603 |   scores.forEach((v, i) => { if (i > 0) ctx.lineTo(xFn(i), yFn(v)); });
 604 |   ctx.strokeStyle = '#58a6ff';
 605 |   ctx.lineWidth   = 2;
 606 |   ctx.lineJoin    = 'round';
 607 |   ctx.stroke();
 608 | 
 609 |   const special = new Set([0, scores.length - 1,
 610 |     scores.indexOf(Math.min(...scores)), scores.indexOf(Math.max(...scores))]);
 611 |   ctx.textAlign = 'center';
 612 |   special.forEach(i => {
 613 |     const x = xFn(i), y = yFn(scores[i]);
 614 |     ctx.beginPath();
 615 |     ctx.arc(x, y, 2.5, 0, Math.PI * 2);
 616 |     ctx.fillStyle = '#58a6ff';
 617 |     ctx.fill();
 618 |     const labelY = y < pad.t + 12 ? y + 12 : y - 5;
 619 |     ctx.fillStyle = '#8b949e';
 620 |     ctx.font = '9px sans-serif';
 621 |     ctx.fillText(scores[i], x, labelY);
 622 |   });
 623 | 
 624 |   ctx.fillStyle = '#8b949e';
 625 |   ctx.font = '9px sans-serif';
 626 |   ctx.textAlign = 'left';
 627 |   ctx.fillText(fmtDate(points[0].ts), pad.l, H - 4);
 628 |   ctx.textAlign = 'right';
 629 |   ctx.fillText(fmtDate(points.at(-1).ts), W - pad.r, H - 4);
 630 | }
 631 | 
 632 | function fmtDate(ts) {
 633 |   const d = new Date(ts);
 634 |   return `${d.getMonth()+1}/${d.getDate()} ${d.getHours()}:${String(d.getMinutes()).padStart(2,'0')}`;
 635 | }
