 827 | // ── Floating button physics ────────────────────────────────────────────────
 828 | let _floatX = 0, _floatY = 0;       // current position (px)
 829 | let _floatVX = 2.2, _floatVY = 1.7; // velocity (px per frame)
 830 | let _floatAngle = 0;                 // current rotation (deg)
 831 | let _floatSpin  = 1.8;               // rotation speed (deg per frame)
 832 | let _floatT     = 0;                 // time counter for opacity sine wave
 833 | let _floatRafId  = null;
 834 | let _floatPaused = false;
 835 | 
 836 | function _floatLoop() {
 837 |   const btn = document.getElementById('random-ticker-btn');
 838 |   if (!btn) return;
 839 | 
 840 |   if (!_floatPaused) {
 841 |     const bw = btn.offsetWidth  || 90;
 842 |     const bh = btn.offsetHeight || 26;
 843 |     const maxX = window.innerWidth  - bw;
 844 |     const maxY = window.innerHeight - bh;
 845 | 
 846 |     _floatX += _floatVX;
 847 |     _floatY += _floatVY;
 848 | 
 849 |     // Bounce off edges
 850 |     if (_floatX <= 0)    { _floatX = 0;    _floatVX = Math.abs(_floatVX); }
 851 |     if (_floatX >= maxX) { _floatX = maxX; _floatVX = -Math.abs(_floatVX); }
 852 |     if (_floatY <= 0)    { _floatY = 0;    _floatVY = Math.abs(_floatVY); }
 853 |     if (_floatY >= maxY) { _floatY = maxY; _floatVY = -Math.abs(_floatVY); }
 854 | 
 855 |     _floatAngle += _floatSpin;
 856 |     _floatT     += 0.025;  // sine wave speed — lower = slower fade
 857 | 
 858 |     const opacity = 0.3 + 0.7 * (Math.sin(_floatT) * 0.5 + 0.5);
 859 | 
 860 |     btn.style.left      = _floatX + 'px';
 861 |     btn.style.top       = _floatY + 'px';
 862 |     btn.style.transform = `rotate(${_floatAngle}deg)`;
 863 |     btn.style.opacity   = opacity;
 864 |   }
 865 | 
 866 |   _floatRafId = requestAnimationFrame(_floatLoop);
 867 | }
 868 | 
 869 | // Randomly pause for 0.8–2.5 s, then resume in a new direction; repeats every 4–10 s
 870 | function _scheduleNextPause() {
 871 |   const delay    = 4000 + Math.random() * 6000;   // wait 4–10 s before pausing
 872 |   const duration = 800  + Math.random() * 1700;   // stay paused 0.8–2.5 s
 873 |   setTimeout(() => {
 874 |     _floatPaused = true;
 875 |     setTimeout(() => {
 876 |       // Pick a fresh random direction at the same speed
 877 | 
 878 |       const angle = Math.random() * 2 * Math.PI;
 879 |       const speed = 2.5;
 880 |       _floatVX = Math.cos(angle) * speed;
 881 |       _floatVY = Math.sin(angle) * speed;
 882 |       // Pick a new random spin speed (1–3 deg/frame, random direction)
 883 |       _floatSpin = (1 + Math.random() * 2) * (Math.random() < 0.5 ? 1 : -1);
 884 |       _floatPaused = false;
 885 |       _scheduleNextPause();
 886 |     }, duration);
 887 |   }, delay);
 888 | }
