 895 |   _floatY = Math.random() * (window.innerHeight - (btn.offsetHeight || 26));
 896 |   // Random direction, consistent speed
 897 |   const angle = Math.random() * 2 * Math.PI;
 898 |   const speed = 2.5;
 899 |   _floatVX = Math.cos(angle) * speed;
 900 |   _floatVY = Math.sin(angle) * speed;
 901 |   _floatRafId = requestAnimationFrame(_floatLoop);
 902 |   _scheduleNextPause();
 903 | }
