1008 | // ── Audio ping via Web Audio API ──────────────────────────────────────────
1009 | function _playAlertPing() {
1010 |   try {
1011 |     const ctx  = new (window.AudioContext || window.webkitAudioContext)();
1012 |     const osc  = ctx.createOscillator();
1013 |     const gain = ctx.createGain();
1014 |     osc.connect(gain);
1015 |     gain.connect(ctx.destination);
1016 |     osc.type = 'sine';
1017 |     osc.frequency.setValueAtTime(ALERT_SOUND_HZ, ctx.currentTime);
1018 |     gain.gain.setValueAtTime(0.18, ctx.currentTime);
1019 |     gain.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + 0.6);
1020 |     osc.start(ctx.currentTime);
1021 |     osc.stop(ctx.currentTime + 0.6);
1022 |   } catch (_) { /* blocked without user gesture — skip silently */ }
1023 | }
