 150 | // ── Ticker scramble ───────────────────────────────────────────────────────
 151 | const SCRAMBLE_CHARS = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789#@$%&';
 152 | 
 153 | function scrambleTicker(anchorEl, realTicker) {
 154 |   const len      = realTicker.length;
 155 |   const totalMs  = 1100;          // total duration
 156 |   const frameMs  = 45;            // ms per frame
 157 |   const frames   = Math.round(totalMs / frameMs);
 158 |   // each character resolves after a staggered portion of the total frames
 159 |   const resolveAt = realTicker.split('').map((_, i) =>
 160 |     Math.round(frames * (0.35 + (i / len) * 0.55))
 161 |   );
 162 | 
 163 |   let frame = 0;
 164 |   const iv = setInterval(() => {
 165 |     frame++;
 166 |     const display = realTicker.split('').map((ch, i) => {
 167 |       if (frame >= resolveAt[i]) return ch;
 168 |       return SCRAMBLE_CHARS[Math.floor(Math.random() * SCRAMBLE_CHARS.length)];
 169 |     }).join('');
 170 | 
 171 |     // Keep the ↗ suffix that's part of the link text
 172 |     anchorEl.textContent = display + ' ↗';
 173 | 
 174 |     if (frame >= frames) {
 175 |       clearInterval(iv);
 176 |       anchorEl.textContent = realTicker + ' ↗';
 177 |       anchorEl.classList.remove('scrambling');
 178 |     }
 179 |   }, frameMs);
 180 | 
 181 |   anchorEl.classList.add('scrambling');
 182 | }
 183 | 
 184 | function scrambleRandomCard(grid, sorted) {
 185 |   if (!sorted.length) return;
 186 |   const pick   = sorted[Math.floor(Math.random() * sorted.length)];
 187 |   const card   = grid.querySelector(`[data-ticker="${pick.ticker}"]`);
 188 |   if (!card) return;
 189 |   const anchor = card.querySelector('.row-ticker-sym');
 190 |   if (!anchor) return;
 191 |   scrambleTicker(anchor, pick.ticker);
 192 | }
