 592 |   ctx.beginPath();
 593 |   ctx.moveTo(xFn(0), yFn(scores[0]));
 594 |   scores.forEach((v, i) => { if (i > 0) ctx.lineTo(xFn(i), yFn(v)); });
 595 |   ctx.lineTo(xFn(scores.length - 1), pad.t + iH);
 596 |   ctx.lineTo(xFn(0), pad.t + iH);
 597 |   ctx.closePath();
 598 |   ctx.fillStyle = grad;
 599 |   ctx.fill();
