1460 |   // Master gain so we can fade the whole laugh out at the end
1461 |   const master = ctx.createGain();
1462 |   master.gain.setValueAtTime(0.55, ctx.currentTime);
1463 |   master.gain.linearRampToValueAtTime(0, ctx.currentTime + 2.4);
1464 |   master.connect(ctx.destination);
1465 | 
1466 |   // Each "laugh voice" is a short burst of descending tones
1467 |   // We layer several voices with different timings & pitches for a crowd feel
1468 |   const voices = [
1469 |     { baseFreq: 420, offset: 0.00, count: 5, speed: 0.13, vol: 0.55 },
1470 |     { baseFreq: 370, offset: 0.05, count: 6, speed: 0.12, vol: 0.45 },
1471 |     { baseFreq: 500, offset: 0.02, count: 4, speed: 0.15, vol: 0.35 },
1472 |     { baseFreq: 340, offset: 0.08, count: 5, speed: 0.11, vol: 0.40 },
1473 |     { baseFreq: 460, offset: 0.03, count: 6, speed: 0.14, vol: 0.30 },
1474 |     { baseFreq: 390, offset: 0.11, count: 4, speed: 0.13, vol: 0.38 },
1475 |   ];
1476 | 
1477 |   voices.forEach(({ baseFreq, offset, count, speed, vol }) => {
1478 |     for (let i = 0; i < count; i++) {
1479 |       const t = ctx.currentTime + offset + i * speed;
1480 | 
1481 |       // Each "ha" = a quick pitch-bend from high → low (the "ha" shape)
1482 |       const osc  = ctx.createOscillator();
1483 |       const gain = ctx.createGain();
1484 | 
1485 |       osc.type = 'sine';
1486 |       // Slight random variation so voices don't sound identical
1487 |       const freq = baseFreq * (1 + (Math.random() - 0.5) * 0.12);
1488 |       osc.frequency.setValueAtTime(freq * 1.18, t);
1489 |       osc.frequency.exponentialRampToValueAtTime(freq * 0.72, t + 0.09);
1490 | 
1491 |       // Attack → short sustain → decay envelope
1492 |       gain.gain.setValueAtTime(0, t);
1493 |       gain.gain.linearRampToValueAtTime(vol, t + 0.018);
1494 |       gain.gain.setValueAtTime(vol,       t + 0.055);
1495 |       gain.gain.exponentialRampToValueAtTime(0.001, t + 0.115);
1496 | 
1497 |       osc.connect(gain);
1498 |       gain.connect(master);
1499 |       osc.start(t);
1500 |       osc.stop(t + 0.13);
1501 | 
1502 |       // Add a subtle overtone (2nd harmonic) for a more "vocal" texture
1503 |       const osc2  = ctx.createOscillator();
1504 |       const gain2 = ctx.createGain();
1505 |       osc2.type = 'triangle';
1506 |       osc2.frequency.setValueAtTime(freq * 2.2, t);
1507 |       osc2.frequency.exponentialRampToValueAtTime(freq * 1.4, t + 0.09);
1508 |       gain2.gain.setValueAtTime(0, t);
1509 |       gain2.gain.linearRampToValueAtTime(vol * 0.22, t + 0.018);
1510 |       gain2.gain.exponentialRampToValueAtTime(0.001, t + 0.10);
1511 |       osc2.connect(gain2);
1512 |       gain2.connect(master);
1513 |       osc2.start(t);
1514 |       osc2.stop(t + 0.12);
1515 |     }
1516 |   });
1517 | 
1518 |   // Auto-close the AudioContext after the laugh finishes
1519 |   setTimeout(() => { try { ctx.close(); } catch (_) {} }, 2600);
1520 | }
