1537 | // ══════════════════════════════════════════════════════════════════════════════
1538 | // LIVE FEED — Continuously pumps fresh top picks into the card grid
1539 | // ══════════════════════════════════════════════════════════════════════════════
1540 | 
1541 | const FEED_INTERVAL_MS = 9000;
1542 | const FEED_SECTORS     = ['all', 'Technology', 'Healthcare', 'Financials', 'Consumer', 'Energy', 'Industrials'];
1543 | const FEED_MODES       = ['random', 'balanced', 'momentum', 'value', 'quality', 'technical'];
1544 | const FEED_MAX_CARDS   = 30;
1545 | 
1546 | let _feedRunning       = false;
1547 | let _feedTimerId       = null;
1548 | let _feedProgressTimer = null;
1549 | let _feedStockPool     = [];
1550 | let _feedCycleStart    = 0;
1551 | 
1552 | function toggleLiveFeed() {
1553 |   if (_feedRunning) stopLiveFeed();
1554 |   else              startLiveFeed();
1555 | }
1556 | 
1557 | function startLiveFeed() {
1558 |   _feedRunning = true;
1559 |   const btn   = document.getElementById('live-toggle');
1560 |   const badge = document.getElementById('live-badge');
1561 |   const bar   = document.getElementById('feed-progress-bar');
1562 |   btn.textContent     = '⏸ Pause Feed';
1563 |   btn.classList.add('active');
1564 |   badge.style.display = 'inline-flex';
1565 |   bar.style.display   = 'block';
1566 | 
1567 |   if (stockData.length > 0) {
1568 |     _feedStockPool = [...stockData];
1569 |     document.getElementById('cards-grid').classList.remove('hidden');
1570 |     document.getElementById('table-head').classList.remove('hidden');
1571 |   }
1572 |   _runFeedCycle();
1573 | }
1574 | 
1575 | function stopLiveFeed() {
1576 |   _feedRunning = false;
1577 |   clearTimeout(_feedTimerId);
1578 |   cancelAnimationFrame(_feedProgressTimer);
1579 |   const btn   = document.getElementById('live-toggle');
1580 |   const badge = document.getElementById('live-badge');
1581 |   const bar   = document.getElementById('feed-progress-bar');
1582 |   const fill  = document.getElementById('feed-progress-fill');
1583 |   btn.textContent     = '▶ Live Feed';
1584 |   btn.classList.remove('active');
1585 |   badge.style.display = 'none';
1586 |   bar.style.display   = 'none';
1587 |   if (fill) fill.style.width = '0%';
1588 | }
1589 | 
1590 | async function _runFeedCycle() {
1591 |   if (!_feedRunning) return;
1592 |   const sector = FEED_SECTORS[Math.floor(Math.random() * FEED_SECTORS.length)];
1593 |   const mode   = FEED_MODES[Math.floor(Math.random() * FEED_MODES.length)];
1594 | 
1595 |   try {
1596 |     const res  = await fetch(`${API}/top-stocks?sector=${encodeURIComponent(sector)}&mode=${mode}`);
1597 |     if (!res.ok) throw new Error('fetch failed');
1598 |     const data = await res.json();
1599 |     const incoming = data.stocks || [];
1600 | 
1601 |     if (incoming.length > 0) {
1602 |       const grid         = document.getElementById('cards-grid');
1603 |       const shownTickers = new Set([...grid.querySelectorAll('.card')].map(c => c.dataset.ticker));
1604 | 
1605 |       const candidate = incoming
1606 |         .sort((a, b) => b.score - a.score)
1607 |         .find(s => !shownTickers.has(s.ticker)) || incoming[0];
1608 | 
1609 |       if (!_feedStockPool.find(s => s.ticker === candidate.ticker)) {
1610 |         _feedStockPool.push(candidate);
1611 |         stockData = _feedStockPool;
1612 |         persistScoreHistory([candidate]);
1613 |       }
1614 | 
1615 |       const card = buildCard(candidate, 1);
1616 |       card.classList.add('card-drop', 'card-glow');
1617 | 
1618 |       if (grid.firstChild) grid.insertBefore(card, grid.firstChild);
1619 |       else grid.appendChild(card);
1620 | 
1621 |       _renumberFeedCards(grid);
1622 |       requestAnimationFrame(() => drawSparkline(candidate));
1623 |       _trimFeedGrid(grid);
1624 | 
1625 |       document.getElementById('last-updated').textContent =
1626 |         'Live · ' + new Date().toLocaleTimeString();
1627 |     }
1628 |   } catch (_) { /* silent — feed keeps going */ }
1629 | 
1630 |   if (_feedRunning) {
1631 |     _feedCycleStart = performance.now();
1632 |     _animateFeedProgress();
1633 |     _feedTimerId = setTimeout(_runFeedCycle, FEED_INTERVAL_MS);
1634 |   }
1635 | }
1636 | 
1637 | function _animateFeedProgress() {
1638 |   const fill = document.getElementById('feed-progress-fill');
1639 |   if (!fill || !_feedRunning) return;
1640 |   const pct = Math.min(((performance.now() - _feedCycleStart) / FEED_INTERVAL_MS) * 100, 100);
1641 |   fill.style.width = pct + '%';
1642 |   if (pct < 100 && _feedRunning) {
1643 |     _feedProgressTimer = requestAnimationFrame(_animateFeedProgress);
1644 |   } else {
1645 |     fill.style.transition = 'none';
1646 |     fill.style.width = '0%';
1647 |     requestAnimationFrame(() => { fill.style.transition = 'width 0.25s linear'; });
1648 |   }
1649 | }
1650 | 
1651 | function _renumberFeedCards(grid) {
1652 |   const medals = ['🥇','🥈','🥉'];
1653 |   [...grid.querySelectorAll('.card')].forEach((card, i) => {
1654 |     const rankEl = card.querySelector('.row-rank');
1655 |     if (!rankEl) return;
1656 |     const rank = i + 1;
1657 |     if (rank <= 3) {
1658 |       rankEl.textContent = medals[rank - 1];
1659 |       rankEl.classList.add('top3');
1660 |     } else {
1661 |       rankEl.textContent = `#${rank}`;
1662 |       rankEl.classList.remove('top3');
1663 |     }
1664 |   });
1665 | }
1666 | 
1667 | function _trimFeedGrid(grid) {
1668 |   const cards = [...grid.querySelectorAll('.card')];
1669 |   if (cards.length <= FEED_MAX_CARDS) return;
1670 |   cards.slice(FEED_MAX_CARDS).forEach(card => {
1671 |     card.style.transition = 'opacity 0.4s ease, transform 0.4s ease';
1672 |     card.style.opacity    = '0';
1673 |     card.style.transform  = 'translateX(20px)';
1674 |     setTimeout(() => card.remove(), 420);
1675 |   });
1676 | }

