320 |   function _sparkSVG(data) {
321 |     const W = 460, H = 48;
322 |     const pts = data;
323 |     const minV = Math.min(...pts), maxV = Math.max(...pts);
324 |     const rng = maxV - minV || 1;
325 |     const xs = pts.map((_, i) => (i / (pts.length - 1)) * W);
326 |     const ys = pts.map(v => H - ((v - minV) / rng) * (H - 4) - 2);
327 |     const d  = xs.map((x, i) => `${i === 0 ? 'M' : 'L'}${x.toFixed(1)},${ys[i].toFixed(1)}`).join(' ');
328 |     const up = pts[pts.length - 1] >= pts[0];
329 |     const col = up ? 'var(--green)' : 'var(--red)';
330 |     const fillD = `${d} L${W},${H} L0,${H} Z`;
331 |     const gid = 'sg' + Math.random().toString(36).slice(2);
332 |     return `<svg viewBox="0 0 ${W} ${H}" xmlns="http://www.w3.org/2000/svg" class="mg-clue-spark">
333 |       <defs>
334 |         <linearGradient id="${gid}" x1="0" y1="0" x2="0" y2="1">
335 |           <stop offset="0%" stop-color="${col}" stop-opacity=".25"/>
336 |           <stop offset="100%" stop-color="${col}" stop-opacity="0"/>
337 |         </linearGradient>
338 |       </defs>
339 |       <path d="${fillD}" fill="url(#${gid})" />
340 |       <path d="${d}" fill="none" stroke="${col}" stroke-width="1.8" stroke-linejoin="round"/>
341 |     </svg>`;
