570 |   // ── Wordle scoring ────────────────────────────────────────────────────────
571 |   // Returns an array of 'correct' | 'present' | 'absent' for each char in guess.
572 |   // Handles duplicate letters correctly with a two-pass consume approach.
573 |   function _scoreGuess(guess, target) {
574 |     const result      = Array(guess.length).fill('absent');
575 |     const targetLeft  = target.split('');   // consumed in pass 2
576 |     const guessLeft   = guess.split('');
577 | 
578 |     // Pass 1 — exact matches (green)
579 |     for (let i = 0; i < guess.length; i++) {
580 |       if (i < target.length && guess[i] === target[i]) {
581 |         result[i]     = 'correct';
582 |         targetLeft[i] = null;   // consumed
583 |         guessLeft[i]  = null;
584 |       }
585 |     }
586 | 
587 |     // Pass 2 — wrong-position matches (yellow)
588 |     for (let i = 0; i < guess.length; i++) {
589 |       if (guessLeft[i] === null) continue;          // already matched
590 |       const ti = targetLeft.indexOf(guessLeft[i]);
591 |       if (ti !== -1) {
592 |         result[i]      = 'present';
593 |         targetLeft[ti] = null;  // consume so duplicates aren't double-counted
594 |       }
595 |     }
596 | 
597 |     return result;
598 |   }
