745 |   // Pick the next letter to reveal using a fixed order:
746 |   // first char → last char → remaining positions left-to-right.
747 |   // Skips positions already in revealedLetters.
748 |   function _revealNextLetter(ticker) {
749 |     const len    = ticker.length;
750 |     if (len === 0) return;
751 | 
752 |     // Build the priority order: first, last, then left-to-right middle chars
753 |     const order = [];
754 |     order.push(0);
755 |     if (len > 1) order.push(len - 1);
756 |     for (let i = 1; i < len - 1; i++) order.push(i);
757 | 
758 |     const next = order.find(i => !revealedLetters.has(i));
759 |     if (next === undefined) return; // all letters already shown
760 |     revealedLetters.add(next);
761 | 
762 |     // Update tiles in-place if the DOM node already exists
763 |     _refreshTiles(ticker);
764 |   }
