882 |   function _ensureDOM() {
883 |     if (document.getElementById('mg-overlay')) {
884 |       overlay   = document.getElementById('mg-overlay');
885 |       card      = overlay.querySelector('.mg-card');
886 |       mascotEl  = overlay.querySelector('.mg-mascot');
887 |       return;
888 |     }
889 |     overlay = document.createElement('div');
890 |     overlay.id = 'mg-overlay';
891 |     card = document.createElement('div');
892 |     card.className = 'mg-card';
893 |     overlay.appendChild(card);
