901 |       <div class="mg-mascot-face">🐂</div>`;
902 |     overlay.appendChild(mascotEl);
903 | 
904 |     document.body.appendChild(overlay);
905 |     overlay.addEventListener('click', e => { if (e.target === overlay) _closeGame(); });
906 |   }
