  const pad = 40;
  const x   = pad + Math.random() * (W - bW - pad * 2);
  const y   = pad + Math.random() * (H - bH - pad * 2);
  btn.style.left = x.toFixed(0) + 'px';
  btn.style.top  = y.toFixed(0) + 'px';
