input.new_text:
/* ── Mute-chase game ── */
#mute-chase-overlay {
  position: fixed;
  inset: 0;
  z-index: 99998;          /* just below the bell burst emojis */
  pointer-events: none;    /* passthrough — only the button is clickable */
}

#mute-chase-label {
  position: fixed;
  top: 0; left: 0; right: 0;
  pointer-events: none;
  text-align: center;
  padding: 6px 0 5px;
  font-size: .72rem;
  font-weight: 700;
  letter-spacing: .08em;
  text-transform: uppercase;
  color: #fff;
  background: rgba(248, 81, 73, .82);
  z-index: 99998;
  animation: mute-label-pulse 0.6s ease-in-out infinite alternate;
}

@keyframes mute-label-pulse {
  from { opacity: .7; }
  to   { opacity: 1; }
}

#mute-chase-countdown {
  display: inline-block;
  margin-left: 10px;
  font-size: .85rem;
  font-variant-numeric: tabular-nums;
  transition: color .3s;
}
#mute-chase-countdown.warn  { color: #ffd700; }
#mute-chase-countdown.panic {
  color: #ff4444;
  animation: countdown-flash .25s ease-in-out infinite alternate;
}
@keyframes countdown-flash {
  from { opacity: 1; }
  to   { opacity: .35; }
}

#mute-chase-btn {
  position: fixed;
  pointer-events: all;
  cursor: pointer;
  z-index: 99999;
  border: none;
  border-radius: 12px;
  padding: 10px 18px;
  font-size: 1rem;
  font-weight: 800;
  background: var(--red, #f85149);
  color: #fff;
  box-shadow: 0 0 18px 4px rgba(248, 81, 73, .7), 0 4px 14px rgba(0,0,0,.5);
  /* NO transition — teleport must be instant */
  user-select: none;
  white-space: nowrap;
  line-height: 1;
}

#mute-chase-btn:hover {
  background: #ff6b63;
}

#mute-chase-btn:active {
  transform: scale(.93);
}

/* ── Page explosion ── */
.page-exploding * {
  animation-play-state: paused !important;   /* freeze everything mid-flight */
}

.page-exploding {
  animation: explosion-flash .35s ease-out forwards;
  overflow: hidden;
}

@keyframes explosion-flash {
  0%   { filter: brightness(1)    saturate(1); }
  15%  { filter: brightness(8)    saturate(3)  hue-rotate(0deg); }
  35%  { filter: brightness(4)    saturate(4)  hue-rotate(20deg); }
  60%  { filter: brightness(2)    saturate(2); }
  100% { filter: brightness(0.05) saturate(0); }
}

.explode-shard {
  position: fixed;
  pointer-events: none;
  user-select: none;
  z-index: 199999;
  font-size: 1.6rem;
  line-height: 1;
  animation: shard-fly var(--shard-dur, 1s) ease-out forwards;
}

@keyframes shard-fly {
  0%   { transform: translate(0,0) scale(.5) rotate(0deg); opacity: 1; }
  70%  { opacity: .8; }
  100% { transform: translate(var(--shard-dx), var(--shard-dy)) scale(1.4) rotate(var(--shard-rot)); opacity: 0; }
}

.explode-card {
  animation: card-fling var(--fling-dur, 700ms) ease-in forwards !important;
  transform-origin: center center;
}

@keyframes card-fling {
  0%   { transform: translate(0,0) rotate(0deg) scale(1); opacity: 1; }
  100% { transform: translate(var(--fling-dx), var(--fling-dy)) rotate(var(--fling-rot)) scale(.2); opacity: 0; }
}

#explosion-screen {
  position: fixed;
  inset: 0;
  z-index: 299999;
  background: #000;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 18px;
  opacity: 0;
  animation: explosion-screen-in .5s ease-out 1.1s forwards;
}

@keyframes explosion-screen-in {
  from { opacity: 0; }
  to   { opacity: 1; }
}

#explosion-screen .expl-skull {
  font-size: 5rem;
  animation: skull-pulse .7s ease-in-out infinite alternate;
}
@keyframes skull-pulse {
  from { transform: scale(1);    filter: drop-shadow(0 0 10px #f85149); }
  to   { transform: scale(1.12); filter: drop-shadow(0 0 30px #f85149); }
}

#explosion-screen .expl-title {
  font-size: 1.5rem;
  font-weight: 900;
  color: #f85149;
  text-align: center;
  letter-spacing: .04em;
  text-shadow: 0 0 20px rgba(248,81,73,.8);
}

#explosion-screen .expl-sub {
  font-size: .85rem;
  color: #888;
  text-align: center;
}

#explosion-screen .expl-restore {
  margin-top: 10px;
  padding: 10px 28px;
  border-radius: 8px;
  border: 2px solid #f85149;
  background: rgba(248,81,73,.15);
  color: #f85149;
  font-size: .9rem;
  font-weight: 700;
  cursor: pointer;
  transition: background .15s;
}
#explosion-screen .expl-restore:hover {
  background: rgba(248,81,73,.3);
}

/* ── Bell burst emojis ── */

