input.new_text:
@property --bump-angle {
  syntax: '<angle>';
  inherits: false;
  initial-value: 0deg;
}

#mute-chase-btn {
  position: fixed;
  pointer-events: all;
  cursor: pointer;
  z-index: 99999;
  border: none;
  border-radius: 12px;
  padding: 10px 18px;
  font-size: 1rem;
  font-weight: 800;
  background: var(--brown, #8B5E3C);
  color: #fff;
  box-shadow: 0 0 18px 4px rgba(139, 94, 60, .7), 0 4px 14px rgba(0,0,0,.5);
  /* NO transition — teleport must be instant */
  user-select: none;
  white-space: nowrap;
  line-height: 1;
  isolation: isolate;   /* keeps ::before behind the button face */
}

/* ── Perimeter bump wave ── */
#mute-chase-btn::before {
  content: '';
  position: absolute;
  inset: -3px;                 /* 3 px border zone on every side */
  border-radius: 15px;         /* 12px + 3px to match the button's corners */
  z-index: -1;
  background: conic-gradient(
    from var(--bump-angle),
    rgba(255,210,160,.15) 0deg,
    rgba(255,210,160,.15) 5deg,
    #f5c97a                    25deg,   /* leading edge of bump */
    #fff5dc                    40deg,   /* bright peak           */
    #f5c97a                    55deg,   /* trailing edge         */
    rgba(255,210,160,.15) 75deg,
    rgba(255,210,160,.15) 360deg
  );
  animation: bump-ride 1.8s linear infinite;
}

@keyframes bump-ride {
  from { --bump-angle: 0deg;   }
  to   { --bump-angle: 360deg; }
}

